(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0033.js"] = [{"id":"poem-d7d74962a1e449925e5ba0d3","title":"避地毘陵上王慥使君","author":"贯休","dynasty":"唐","verses":["至理至昭昭，心通即不遥。","圣威无远近，吾道太孤标。","辛苦苏氓俗，端贞荅盛朝。","气高吞海岳，贫甚似渔樵。","庾亮风流澹，刘宽政事超。","清须遭贵遇，隐已被谁招。","栗坞修禅寺，仙香寄石桥。","风雷巡稼穑，鱼鸟合歌谣。","视事私终杀，忧民态亦雕。","道高无不及，恩甚固难消。","大寇山难隔，孤城数合烧。","烽烟终日起，汤沐用心燋。","勇义排千阵，诛锄拟一朝。","誓盟违日月，旌斾过寒潮。","古驿江云入，荒宫海雨飘。","仙松添瘦碧，天骥减丰臕。","似在陈兼卫，终为宋与姚。","已观云似鹿，即报首皆枭。","尽愿回清镜，重希在此条。","应怜千万户，祷祝向唐尧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-480e4f20-0fd6-4a06-97bf-2b5d4bd7b2f3","tags":[]},{"id":"poem-d7da95b7b8d3d34cae5085c1","title":"清平乐·云峰秀叠","author":"毛滂","dynasty":"宋","verses":["云峰秀叠。","露冷琉璃叶。","北畔娑罗花弄雪。","香度小桥淡月。","与君踏月寻花。","玉人双捧流霞。","吸尽杯中花月，仙风相送还家。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-715","tags":[]},{"id":"poem-d7e78fc6049b89ea42218880","title":"又游仙诗一绝","author":"曹唐","dynasty":"唐","verses":["靖节先生几代孙，青娥曾接玉郎魂。","春风流水还无赖，偷放桃花出洞门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8ca3f847-34a1-46f4-ba4a-4c7cd0d8dc7e","tags":[]},{"id":"poem-d7f3e3dc777c9ef858e5eefa","title":"送戴征士还山","author":"李端","dynasty":"唐","verses":["柔桑锦臆雉，相送到烟霞。","独隐空山里，闲门几树花。","草生杨柳岸，鸟啭竹林家。","不是谋生拙，无为末路赊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3adb71b6-f985-49f8-8c0d-cda8ddd64891","tags":[]},{"id":"poem-d7f9a2812d99bae0061f3832","title":"临江仙·寒食清明春事好","author":"韩淲","dynasty":"宋","verses":["寒食清明春事好，公家霁月光风。","年时犹记雨声中。","州侯陈乐舞，法从酒杯同。","坐上王杨虽自散，酴醿依旧香浓。","待将诗易寿无穷。","鸢飞鱼跃矣，风虎更云龙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-471","tags":[]},{"id":"poem-d808fbbd5f53d6401b0dc887","title":"鸿雁","author":"佚名","dynasty":"先秦","verses":["鸿雁于飞，肃肃其羽。之子于征，劬劳于野。爰及矜人，哀此鳏寡。","鸿雁于飞，集于中泽。之子于垣，百堵皆作。虽则劬劳，其究安宅？","鸿雁于飞，哀鸣嗷嗷。维此哲人，谓我劬劳。维彼愚人，谓我宣骄。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-180","tags":[]},{"id":"poem-d80c1240d2c69f4205022368","title":"相和歌辞 子夜四时歌四首 夏歌","author":"李白","dynasty":"唐","verses":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若邪。","回舟不待月，归去越王家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4bd5be2b-5788-42c0-a300-9d106a73d46e","tags":["唐诗三百首","清商曲辞","夏天","乐府","哲理","写人","荷花"]},{"id":"poem-d81400e86f41caa664a5113a","title":"新安官舍闲坐","author":"来鹄","dynasty":"唐","verses":["寂寞空阶草乱生，簟凉风动若为情。","不知独坐闲多少，看得蜘蛛结网成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-925263e8-e4f6-4a92-bab9-263e10418963","tags":[]},{"id":"poem-d819d76b094be3e28d5f05b4","title":"喜闻收复河陇","author":"张祜","dynasty":"唐","verses":["诏书频降尽论边，将择英雄相卜贤。","河陇已耕曾殁（陈九思同志疑当作「没」。","）地，犬羊谁辩却朝天。","高悬日月胡沙外，遥拜旌旗汉垒前。","共感垂衣匡济力，华夷同见太平年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-73d9da07-8db0-416e-a855-300d77d61ac6","tags":[]},{"id":"poem-d81fd4cc07bfc026dab5ec35","title":"挽令人","author":"王十朋","dynasty":"宋","verses":["糟糠情味饱相谙，我事耕耘尔力蚕。","误走迷途半天下，忽惊魂梦断泉南。","二年旅榇悲无奈，千里途车涕不堪。","预卜黄华晚秋节，佳城归祔白岩庵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b3787fd3-facf-4591-9e29-ac34daa31089","tags":[]},{"id":"poem-d82ab95134132480ff274998","title":"赠皇甫垣","author":"赵嘏","dynasty":"唐","verses":["养由弓箭已无功，牢落生涯事事同。","相劝一杯寒食酒，几多辛苦到春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d52f23e0-29a9-4dab-9359-a0a0597c4853","tags":[]},{"id":"poem-d83290a34eba3a20bf893c1d","title":"却入泗口","author":"李绅","dynasty":"唐","verses":["洪河一派清淮接，堤草芦花万里秋。","烟树寂寥分楚泽，海云明灭满扬州。","望深江汉连天远，思起乡闾满眼愁。","惆怅路岐真此处，夕阳西没水东流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b92fefdd-ddbc-478b-8d8d-8724abe2176d","tags":[]},{"id":"poem-d835f807d2a1d930c9258a20","title":"九歌·大司命","author":"屈原","dynasty":"先秦","verses":["广开兮天门，纷吾乘兮玄云。","令飘风兮先驱，使涷雨兮洒尘。","君回翔兮以下，逾空桑兮从女。","纷总总兮九州，何寿夭兮在予。","高飞兮安翔，乘清气兮御阴阳。","吾与君兮齐速，导帝之兮九坑。","灵衣兮被被，玉佩兮陆离。","一阴兮一阳，众莫知兮余所为。","折疏麻兮瑶华，将以遗兮离居。","老冉冉兮既极，不寖近兮愈疏。","乘龙兮辚辚，高驰兮冲天。","结桂枝兮延伫，羌愈思兮愁人。","愁人兮奈何，愿若今兮无亏。","固人命兮有当，孰离合兮何为？"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-5","tags":[]},{"id":"poem-d8387d33065abaf351a310f7","title":"送达夫同年殿丞宰吴江","author":"苏颂","dynasty":"宋","verses":["尝夸吴会土风嘉，新领铜章一水涯。","岂为江山游赏胜，只贪晨夕旨甘奢。","鱼登盘俎霜萦缕，苹满洲汀雪吐花。","旧令多才君继美，松陵赓唱未应赊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cdb6ba35-c0ff-4f39-a649-d240efb7a92c","tags":[]},{"id":"poem-d83f7a982aa2bac8fcff31ec","title":"更漏子·烟月寒","author":"毛熙震","dynasty":"五代","verses":["烟月寒，秋夜静，漏转金壶初永。","罗幕下，绣屏空，灯花结碎红。","人悄悄，愁无了，思梦不成难晓。","长忆得，与郎期，窃香私语时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-43","tags":[]},{"id":"poem-d843297256ce87601fb2c7df","title":"天末忆李白","author":"杜甫","dynasty":"唐","verses":["凉风起天末，君子意如何。","鸿雁几时到，江湖秋水多。","文章憎命达，魑魅喜人过。","应共冤魂语，投诗赠汩罗。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2c036362-9f1d-434c-854f-b97a2a4bb19b","tags":["唐诗三百首","写风","五言律诗","风","怀人"]},{"id":"poem-d8462b8ef6a86672cf54f869","title":"游城东王驸马亭","author":"陆畅","dynasty":"唐","verses":["城外无尘水间松，秋天木落见山容。","共寻萧史江亭去，一望终南紫阁峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-578523ba-355b-4d06-8712-167e08b76262","tags":[]},{"id":"poem-d84cb66599b29496a897ceb4","title":"巫山高","author":"李贺","dynasty":"唐","verses":["碧丛丛，高插天，大江翻澜神曳烟。","楚魂寻梦风飔然，晓风飞雨生苔钱。","瑶姬一去一千年，丁香筇竹啼老猨。","古祠近月蟾桂寒，椒花坠红湿云间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-05184315-6703-4e60-b85a-57b887c2b7c0","tags":["写山","写景","描写山"]},{"id":"poem-d85b1bd68950d1716b1842ed","title":"寄紫阁隐者","author":"贯休","dynasty":"唐","verses":["积翠藏一叟，常思未得游。","不知在岩下，为复在峰头。","苔上枯藤笐，泉淋破石楼。","伊余更何事，不学此翁休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ef62eaac-02c0-48eb-a6a1-23c45c4fe25e","tags":[]},{"id":"poem-d85d8fced76307a27ad19400","title":"浪淘沙·往事只堪哀","author":"李煜","dynasty":"五代","verses":["往事只堪哀，对景难排。","秋风庭院藓侵阶。","一任珠帘闲不卷，终日谁来？","金剑已沉埋，壮气蒿莱。","晚凉天净月华开。","想得玉楼瑶殿影，空照秦淮。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-25","tags":[]},{"id":"poem-d85e1944e3ee55bc4c6f5db8","title":"小游仙诗九十八首 九十一","author":"曹唐","dynasty":"唐","verses":["溪影沉沙树影清，人家皆踏五音行。","可怜三十六天路，星月满空琼草青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-389bbb28-98a3-4944-9b85-f1ece5b7cebe","tags":[]},{"id":"poem-d86029d6cea59b05bd983cab","title":"闻蛙","author":"苏颂","dynasty":"宋","verses":["蛙黾何所恃，喧喧矜善鸣。","不知秽污质，群沸沼池清。","游子得无泪，羁人若为情。","华堂有丝竹，皆厌尔虚声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-863572d5-7f46-4322-8d73-7f2acc1c53bd","tags":[]},{"id":"poem-d861cf53f116517d635285eb","title":"寄刘员外长卿","author":"皇甫曾","dynasty":"唐","verses":["南忆新安郡，千山带夕阳。","断猨知夜久，秋草助江长。","疎发应成素，青松独耐霜。","爱才称汉主，题柱待回乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-997fc4da-ca67-42e2-99c4-7bd68a155c8a","tags":[]},{"id":"poem-d868dedf13149dce5bbaf4fe","title":"登长城","author":"李益","dynasty":"唐","verses":["汉家今上郡，秦塞古长城。","有日云长惨，无风沙自惊。","当今圣天子，不战四夷平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b9fa15f5-c7ac-40b3-998f-6ae03ba52122","tags":[]},{"id":"poem-d86b019335455da5912ecfc1","title":"清平乐·塞鸿去矣","author":"纳兰性德","dynasty":"清","verses":["塞鸿去矣，锦字何时寄。","记得灯前佯忍泪，却问明朝行未。","别来几度如珪，飘零落叶成堆。","一种晓寒浅梦，妻凉毕竟因谁。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-66","tags":[]},{"id":"poem-d86e1c755d35eaf677096bac","title":"木兰花・玉楼春·燕鸿过后莺归去","author":"晏殊","dynasty":"宋","verses":["燕鸿过后莺归去。","细算浮生千万绪。","长于春梦几多时，散似秋云无觅处。","闻琴解佩神仙侣。","挽断罗衣留不住。","劝君莫作独醒人，烂醉花间应有数。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-163","tags":["宋词三百首"]},{"id":"poem-d86f03261936ac6d4a9643eb","title":"离亭宴·捧黄封诏卷","author":"张先","dynasty":"宋","verses":["捧黄封诏卷。","随处是、离亭别宴。","红翠成轮歌未遍。","已恨野桥风便。","此去济南非久，惟有凤池鸾殿。","三月花飞几片。","又减却、芳菲过半。","千里恩深云海浅。","民爱比、春流不断。","更上玉楼西，归雁与、征帆共远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-372","tags":[]},{"id":"poem-d883c872ce52bb6e5256e405","title":"襄阳曲","author":"子兰","dynasty":"唐","verses":["为忆南游人，移家大堤住。","千帆万帆来，尽过门前去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b68b9b6b-5e96-411e-8804-8943f8d2ae10","tags":[]},{"id":"poem-d88a6dab7181c9c88f104795","title":"吴门柳・渔家傲·啸度万松千步岭","author":"贺铸","dynasty":"宋","verses":["啸度万松千步岭。","钱湖门外非尘境。","见底碧漪如眼净。","岚光映。","镜屏百曲新磨莹。","好月为人重破瞑。","云头艳艳开金饼。","传语桂娥应奈静。","堪乘兴。","尊前听我游仙咏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-104","tags":[]},{"id":"poem-d892745637e72b6d5b74f80a","title":"郑容全成蛟形木机歌","author":"皎然","dynasty":"唐","verses":["万物贵天然，天然不可得。","浑朴无劳剞劂工，幽姿自可蛟龙质。","欲腾未去何翩翩，扬袂争前谁敢拂。","可中风雨一朝至，还应不是池中物。","苍山万重采一枝，形如器车生意奇。","风号雨喷心不折，众木千丛君独知。","高人心，多越格。","有时就月吟春风，持来座右惊神客。","爱君开合江之滨，白云黄鹤长相亲。","南郭子綦我不识，非君独是是何人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d0e20fd2-4917-4eeb-9bb1-27f12313ea48","tags":[]},{"id":"poem-d89fd4db7ff84fe67e5fc138","title":"满江红·人倚金铺","author":"蔡伸","dynasty":"宋","verses":["人倚金铺，颦翠黛、盈盈堕睫。","话别处、留连无计，语娇声咽。","十幅云帆风力满，一川烟暝波光阔。","但回首、极目望高城，弹清血。","并兰舟，停画楫。","曾共醉，津亭月。","销魂处，今夜月圆人缺。","楚岫云归空怅望，汉皋佩解成轻别。","最苦是、拍塞满怀愁，无人说。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-942","tags":[]},{"id":"poem-d8a819d2cf6621eb58282700","title":"菩萨蛮·月华如水笼香砌","author":"孙光宪","dynasty":"五代","verses":["月华如水笼香砌，金环碎撼门初闭。","寒影堕高檐，钩垂一画帘。","碧烟轻袅袅，红战灯花笑。","即此是高唐，掩屏秋梦长。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-0","tags":[]},{"id":"poem-d8ac7f6d0d973a7abf487e5d","title":"纪汤泉","author":"贾岛","dynasty":"唐","verses":["维泉肇何代，开凿同二仪。","五行分水火，厥用谁一之。","在卦得既济，备象坎与离。","下有风轮煽，上有雷车驰。","霞掀祝融井，日烂扶桑池。","气殊𬒈石厉，脉有灵砂滋。","骊山岂不好，玉环污流脂。","至今华清树，空遗后人悲。","遐哉哲人逝，此水真吾师。","一濯三沐髪，六凿还希夷。","伐毛返骨髓，髪白令人黟。","十年走尘土，负我汗漫期。","再来池上游，触热三伏时。","古寺僧寂寞，但余壁上诗。","不见题诗人，令我长叹咨。","（见康熙十八年闵麟嗣撰《黄山志定本》卷六，乾隆间刊印。","此诗承仪征吴白匋先生见告。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-be609e91-15fb-4ef7-ac6b-f6874e876d15","tags":["黄山"]},{"id":"poem-d8b12781152bcdefa408f657","title":"送陈择之","author":"张栻","dynasty":"宋","verses":["君能千里来，乃作触热去。","凉秋幸非遥，归计无已遽。","向来文字间，讲论有平素。","及兹共王事，益得君佳处。","几微独深窥，圭角本不露。","岂期寂寞滨，获此友朋助。","吾邦虽云僻，山水足奇趣。","更期休沐晨，相与穷杖屦。","匆匆何少悰，咄咄出别语。","君怀负丞恩，行矣当及戍。","我亦念归欤，霜天收栗芋。","后会未可期，往事屡回顾。","赠言复何有，独以此道故。","寥寥千载前，达者同一路。","所趋固绝尘，所履无虚步。","临深觉居高，仰止有余慕。","要须学沧溟，汇此百川注。","他年傥相忆，访我城南圃。","无使岁月深，永思编简蠹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-519014c2-deb8-4572-995c-c8a259049467","tags":[]},{"id":"poem-d8b8766363d00c7f70d8fa3d","title":"六月","author":"佚名","dynasty":"先秦","verses":["六月栖栖，戎车既饬。四牡骙骙，载是常服。𤞤狁孔炽，我是用急。王于出征，以匡王国。","比物四骊，闲之维则。维此六月，既成我服。我服既成，于三十里。王于出征，以佐天子。","四牡修广，其大有颙。薄伐𤞤狁，以奏肤公。有严有翼，共武之服。共武之服，以定王国。","𤞤狁匪茹，整居焦获。侵镐及方，至于泾阳。织文鸟章，白旆央央。元戎十乘，以先启行。","戎车既安，如轾如轩。四牡既佶，既佶且闲。薄伐𤞤狁，至于大原。文武吉甫，万邦为宪。","吉甫燕喜，既多受祉。来归自镐，我行永久。饮御诸友，炰鳖脍鲤。侯谁在矣？张仲孝友。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-176","tags":[]},{"id":"poem-d8c754a9921ae333dc3cf789","title":"桂林道中二首  其二","author":"李纲","dynasty":"宋","verses":["时危远谪堕南峦，犹在乾坤覆载间。","瘴雨岚烟殊气候，玉簪罗带巧溪山。","桄榔叶暗伤心碧，踯躅花开满目斑。","惟有月华依旧好，清辉应与照云鬟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6559e536-e4a3-4787-a06a-1ed54f7bede7","tags":[]},{"id":"poem-d8d2f61e1a6e578292e56dd4","title":"横吹曲辞 折杨柳","author":"欧阳瑾","dynasty":"唐","verses":["垂柳拂妆台，葳蕤叶半开。","年华枝上见，边思曲中来。","嫩色宜新雨，轻花伴落梅。","朝朝倦攀折，征戍几时回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ba115d1b-606c-4751-af66-e617b670babd","tags":[]},{"id":"poem-d8d4e395d72b262e64d6aa3c","title":"丽正殿赐宴同勒天前烟年四韵应制","author":"王湾","dynasty":"唐","verses":["金殿忝陪贤，琼羞忽降天。","鼎罗仙掖里，觞拜琐闱前。","院逼青霄路，厨和紫禁烟。","酒酣空忭舞，何以荅昌年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-076db65b-9bc5-42e9-b146-28e50e39fc50","tags":[]},{"id":"poem-d8e3fac8ca832f4fa7d30eb3","title":"春日登大悲阁二首（一字至七字） 一","author":"钱惟治","dynasty":"唐","verses":["阁，阁。","雕镂，彩错。","簇明霞，攅丽萼。","玉女窥牖，飞仙捧铎。","沉烟燠宝香，媚水涵珠箔。","千山蓊郁晴霁，万井喧填晓郭。","登临徙倚傍琼栏，满目春光煦寥廓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b6d9d152-f9d5-4c45-8134-22af151d4a77","tags":[]},{"id":"poem-d8ed58f1c3b39c7e9a35a7f2","title":"送清会上人游京","author":"皎然","dynasty":"唐","verses":["佳游限衰疾，一笑向西风。","思见青门外，曾临素浐东。","峰明云际寺，日出露寒宫。","行道禅长在，香尘不染空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-09aaf32b-3623-4c87-a46e-36a12b7a31d3","tags":[]},{"id":"poem-d8f7d0c114c5fcf514ea80a8","title":"羊角埂晚行","author":"宋伯仁","dynasty":"宋","verses":["葛裙蒲履帽乌纱，迤逦乘凉到水涯。","数寺晚钟声未歇，满身明月看荷花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8dcb2c32-3758-4f7a-a340-60fd629857b9","tags":[]},{"id":"poem-d901a4de193dff0b6c1c773c","title":"诗九首托南剑刘教寻亦周墓焚之  其二","author":"赵文","dynasty":"宋","verses":["舜卿墓表屹东禅，却恐如今不得全。","崇胜山中一堆土，故应汝骨尚依然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6f79cadf-0ac0-41ab-8599-56b744e58d01","tags":[]},{"id":"poem-d9081853466d9f2bb751956c","title":"摊破浣溪沙・山花子·曲磴斜阑出翠微","author":"贺铸","dynasty":"宋","verses":["曲磴斜阑出翠微。","西州回首思依依。","风物宛然长在眼，只人非。","绿树隔巢黄鸟并，沧洲带雨白鸥飞。","多谢子规啼劝我，不如归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-98","tags":[]},{"id":"poem-d90eb1e1f71f717915645273","title":"渭水西别李仑","author":"崔国辅","dynasty":"唐","verses":["陇右长亭堠，山阴古塞秋。","不知呜咽水，何事向西流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-75f247a1-875a-48dd-87c2-6e8cd5c13140","tags":[]},{"id":"poem-d91338030799668e32310c06","title":"问遥山禅老","author":"皎然","dynasty":"唐","verses":["天与松子寿，独饮日月精。","复令颜子贤，胡为夭其生。","吾将寻河源，上天问天何不平。","我将诘仙老，大道无私谁强名。","仙老难逢天不近，世人何人解应尽。","明朝欲向翅头山，问取禅公此义还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9f0efffd-61e5-412c-9804-789f66959bbc","tags":[]},{"id":"poem-d9156ef4437bab139be1553c","title":"临江仙·暮蝉声尽落斜阳","author":"毛文锡","dynasty":"五代","verses":["暮蝉声尽落斜阳，银蟾影挂潇湘。","黄陵庙侧水茫茫。楚山红树，烟雨隔高唐。","岸泊渔灯风飐碎，白苹远散浓香。","灵娥鼓瑟韵清商，朱弦凄切，云散碧云长。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-32","tags":[]},{"id":"poem-d91aad52d143a5c54a1bb70b","title":"七谏·沉江","author":"东方朔","dynasty":"汉","verses":["惟往古之得失兮，览私微之所伤。","尧舜圣而慈仁兮，后世称而弗忘。","齐桓失于专任兮，夷吾忠而名彰。","晋献惑于㛤姬兮，申生孝而被殃。","偃王行其仁义兮，荆文寤而徐亡。","纣暴虐以失位兮，周得佐乎吕望。","修往古以行恩兮，封比干之丘垄。","贤俊慕而自附兮，日浸淫而合同。","明法令而修理兮，兰芷幽而有芳。","苦众人之妒予兮，箕子寤而佯狂。","不顾地以贪名兮，心怫郁而内伤。","联蕙芷以为佩兮，过鲍肆而失香。","正臣端其操行兮，反离谤而见攘。","世俗更而变化兮，伯夷饿于首阳。","独廉洁而不容兮，叔齐久而逾明。","浮云陈而蔽晦兮，使日月乎无光。","忠臣贞而欲谏兮，谗谀毁而在旁。","秋草荣其将实兮，微霜下而夜降。","商风肃而害生兮，百草育而不长。","众并谐以妒贤兮，孤圣特而易伤。","怀计谋而不见用兮，岩穴处而隐藏。","成功隳而不卒兮，子胥死而不葬。","世从俗而变化兮，随风靡而成行。","信直退而毁败兮，虚伪进而得当。","追悔过之无及兮，岂尽忠而有功。","废制度而不用兮，务行私而去公。","终不变而死节兮，惜年齿之未央。","将方舟而下流兮，冀幸君之发蒙。","痛忠言之逆耳兮，恨申子之沉江。","愿悉心之所闻兮，遭值君之不聪。","不开寤而难道兮，不别横之与纵。","听奸臣之浮说兮，绝国家之久长。","灭规矩而不用兮，背绳墨之正方。","离忧患而乃寤兮，若纵火于秋蓬。","业失之而不救兮，尚何论乎祸凶。","彼离畔而朋党兮，独行之士其何望？","日渐染而不自知兮，秋毫微哉而变容。","众轻积而折轴兮，原咎杂而累重。","赴湘沅之流澌兮，恐逐波而复东。","怀沙砾而自沉兮，不忍见君之蔽壅。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-31","tags":[]},{"id":"poem-d91bfeb98b1e9f622502990d","title":"秋浦歌","author":"李白","dynasty":"唐","verses":["白发三千丈，离愁似个长。","不知明镜里，何处得秋霜。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋浦歌","tags":[]},{"id":"poem-d91cac9aab82e383e4ae32e0","title":"书雪湖寄张高沙诗卷后","author":"释居简","dynasty":"宋","verses":["大篇如建瓴，小篇如扞城。","执此能事柄，凌夺造物真。","雪湖坐此彻骨贫，致贫之具犹示人。","铿锵应是我辈语，饥鸢悲苦哦清新。","高沙旧日春风手，也是乘槎丈人后。","红莲开幕著诗人，此段风流少人有。","飞声郎署知闻旧，扫门谩惜千金箒。","不图愿与丈人厚，要看云锦三千首。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-eab66aa9-9cae-494d-aadf-b5f64bbc3f37","tags":[]},{"id":"poem-d9213fee34db4e60f9238398","title":"洗苎歌","author":"释居简","dynasty":"宋","verses":["白水浣白苎，濯濯霜不如。","亭匀拣经纬，霜澌寒疎疎。","天质本无玷，况复随时染。","秋阳曝皜皜，不受红紫谄。","丹茸碧缕明相掩，玉手苎纱秋潋潋。","拜了穿针楼上月，细与天孙话新洁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-fb00c660-0a62-4367-985a-d4d178f4622c","tags":[]},{"id":"poem-d924e35220db01f8c757af28","title":"狮子序","author":"无名氏《张协状元》","dynasty":"元","verses":["张协恨时未至，居家出路，长是不利。","(旦)不在疏狂惟在自守己，看造物何如。","(生)张协只仗托诗书。","(旦)奴家惟凭针指。","(合)逆来顺受，须有通时。","(旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2512","tags":[]},{"id":"poem-d928bbf1e27ce5bfb2c18f88","title":"赠皇甫侍御赴都八首 六","author":"元希声","dynasty":"唐","verses":["载怀朋情，尝接闲宴。","好洽昆弟，官联州县。","如彼松竹，春荣冬蒨。","柯叶蔼然，不渝霜霰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-30769653-572f-4c56-8a3c-b01750734092","tags":[]},{"id":"poem-d92c043a0b9f49f0ab9b3698","title":"咏萤","author":"李嘉祐","dynasty":"唐","verses":["映水光难定，凌虚体自轻。","夜风吹不灭，秋露洗还明。","向烛仍分焰，投书更有情。","犹将流乱影，来此傍簷楹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5c23312e-3048-4c55-9912-4d83d982cf18","tags":[]},{"id":"poem-d92f6814499967b21308b123","title":"独游寄衞长林","author":"司空曙","dynasty":"唐","verses":["草绿春阳动，迟迟泽畔游。","恋花同野蝶，爱水剧江鸥。","身外唯须醉，人间尽是愁。","那知鸣玉者，不羡卖瓜侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-362ee93e-9b20-4082-a797-bc339355f3be","tags":[]},{"id":"poem-d93439f9e3758dd5e6fddee4","title":"愁","author":"徐夤","dynasty":"唐","verses":["夜长偏觉漏声迟，往往随歌惨翠眉。","黄叶落催砧杵日，子规啼破梦魂时。","明妃去泣千行泪，蔡琰归梳两鬓丝。","四皓入山招不得，无家归客最堪欺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a59429c9-5135-438d-ba1b-6463f8f1fc50","tags":[]},{"id":"poem-d939140b775689107223de4b","title":"郊行即事","author":"程颢","dynasty":"宋","verses":["芳原绿野恣行时，春入遥山碧四围。","兴逐乱红穿柳巷，困临流水坐苔矶。","莫辞盏酒十分劝，只恐风花一片飞。","况是清明好天气，不妨游衍莫忘归。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-郊行即事","tags":[]},{"id":"poem-d945c11c36c498d58fdd68ee","title":"送友人归山歌二首 二","author":"王维","dynasty":"唐","verses":["山中人兮欲归，云冥冥兮雨霏霏，水惊波兮翠菅靡。","白鹭忽兮翻飞，君不可兮褰衣。","山万重兮一云，混天地兮不分。","树晻暧兮氛氲，猿不见兮空闻。","忽山西兮夕阳，见东臯兮远村。","平芜绿兮千里，眇惆怅兮思君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-837924d5-03d4-4133-8031-d1f042686d65","tags":[]},{"id":"poem-d9460414a55993b2c662718a","title":"菩萨蛮·隔花才歇廉纤雨","author":"纳兰性德","dynasty":"清","verses":["隔花才歇廉纤雨，一声弹指混无语。","梁燕自双归，长条脉脉垂。","小屏山色远，妆薄铅华浅。","独自立瑶阶，透寒金缕鞋。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-189","tags":[]},{"id":"poem-d9480361359efb9c77ab316d","title":"揽秀亭","author":"米芾","dynasty":"宋","verses":["群峰矫矫蛟龙颠，冲波鼓鬣方回旋。","排空刻削万仞碧，秀色直上干云天。","地形天巧世莫测，插出怪变知何年。","傍惊列翠不入手，拟将瘦脊束差肩。","何人高致得入手，择奇结构当其前。","丹甍绣桷丽朝日，绮疏藻井摇非烟。","葱苍数里拂巾被，蓊鬰众木临书筵。","开扉割得晓光莹，绕榻飞来佳气鲜。","乘闲超忽不知已，徒觉四顾清无边。","毫眉主人曳芒履，策杖欲作商宫仙。","犀尊荡漾泻醇醴，招宾集醉秋风莲。","莲华菡萏翠的皪，皎月照耀争婵娟。","金丝锵戛乱两耳，醉倒三百黄金船。","风流不见谢太守，昭亭朗赋磨新镌。","放傲岂如王逸少，兰亭草圣窥天全。","才华墨妙古已远，只今唯有空山川。","孰若开编乐教子，坐使发策惊前贤。","还当操笔俯栏楯，试与采掇供诗篇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d0bffc60-78bb-49f4-8c83-4bec6646a407","tags":[]},{"id":"poem-d94c6555b4201c6bcc38db33","title":"送义兴元少府","author":"李端","dynasty":"唐","verses":["逢君惠连第，初命[便]光辉。","已得群公祖，终妨太傅讥。","路长人反顾，草断燕回飞。","本是江南客，还同衣锦归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4f0445db-513b-4949-ab33-5412bcd8c074","tags":[]},{"id":"poem-d94fdc2e686c67b8586f486c","title":"郊庙歌辞 周宗庙乐舞辞 章德舞","author":"不详","dynasty":"唐","verses":["清庙新，展严禋。","恭祖德，厚人伦。","雅乐荐，礼器陈。","俨皇尸，列虞宾。","神如在，声不闻。","享必信，貌惟夤。","想龙服，奠牺樽。","礼既备，庆来臻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1db83204-895b-41ca-9ad5-502106899bf4","tags":[]},{"id":"poem-d963d8bb1085332eb9d91f39","title":"减字木兰花·烛花摇影","author":"纳兰性德","dynasty":"清","verses":["烛花摇影，冷透疏衾刚欲醒。","待不思量，不许孤眠不断肠。","茫茫碧落，天上人间情一诺。","银汉难通，稳耐风波愿始从。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-208","tags":[]},{"id":"poem-d96a255f06424cc9afc9ff6e","title":"大招","author":"景差","dynasty":"先秦","verses":["青春受谢，白日昭只。","春气奋发，万物遽只。","冥凌浃行，魂无逃只。","魂魄归来！无远遥只。","魂乎归来！无东无西，无南无北只。","东有大海，溺水浟浟只。","螭龙并流，上下悠悠只。","雾雨淫淫，白皓胶只。","魂乎无东！汤谷寂寥只。","魂乎无南！南有炎火千里，蝮蛇蜒只。","山林险隘，虎豹蜿只。","鰅鳙短狐，王虺骞只。","魂乎无南！蜮伤躬只。","魂乎无西！西方流沙，漭洋洋只。","豕首纵目，被发鬤只。","长爪踞牙，诶笑狂只。","魂乎无西！多害伤只。","魂乎无北！北有寒山，趠龙赩只。","代水不可涉，深不可测只。","天白颢颢，寒凝凝只。","魂乎无往！盈北极只。","魂魄归来！闲以静只。","自恣荆楚，安以定只。","逞志究欲，心意安只。","穷身永乐，年寿延只。","魂乎归来！乐不可言只。","五谷六仞，设菰梁只。","鼎臑盈望，和致芳只。","内鸧鸽鹄，味豺羹只。","魂乎归来！恣所尝只。","鲜蠵甘鸡，和楚酪只。","醢豚苦狗，脍苴蒪只。","吴酸蒿蒌，不沾薄只。","魂兮归来！恣所择只。","炙鸹烝凫，煔鹑敶只。","煎鰿膗雀，遽爽存只。","魂乎归来！丽以先只。","四酎并孰，不涩嗌只。","清馨冻饮，不歠役只。","吴醴白蘖，和楚沥只。","魂乎归来！不遽惕只。","代秦郑卫，鸣竽张只。","伏戏《驾辩》，楚《劳商》只。","讴和《扬阿》，赵萧倡只。","魂乎归来！定空桑只。","二八接舞，投诗赋只。","叩钟调磬，娱人乱只。","四上竞气，极声变只。","魂乎归来！听歌譔只。","朱唇皓齿，嫭以姱只。","比德好闲，习以都只。","丰肉微骨，调以娱只。","魂乎归来！安以舒只。","嫮目宜笑，娥眉曼只。","容则秀雅，稚朱颜只。","魂乎归来！静以安只。","姱修滂浩，丽以佳只。","曾颊倚耳，曲眉规只。","滂心绰态，姣丽施只。","小腰秀颈，若鲜卑只。","魂乎归来！思怨移只。","易中利心，以动作只。","粉白黛黑，施芳泽只。","长袂拂面，善留客只。","魂乎归来！以娱昔只。","青色直眉，美目媔只。","靥辅奇牙，宜笑嘕只。","丰肉微骨，体便娟只。","魂乎归来！恣所便只。","夏屋广大，沙堂秀只。","南房小坛，观绝霤只。","曲屋步壛，宜扰畜只。","腾驾步游，猎春囿只。","琼毂错衡，英华假只。","茝兰桂树，郁弥路只。","魂乎归来！恣志虑只。","孔雀盈园，畜鸾皇只！","鹍鸿群晨，杂鹙鸧只。","鸿鹄代游，曼骕骦只。","魂乎归来！凤凰翔只。","曼泽怡面，血气盛只。","永宜厥身，保寿命只。","室家盈廷，爵禄盛只。","魂乎归来！居室定只。","接径千里，出若云只。","三圭重侯，听类神只。","察笃夭隐，孤寡存只。","魂兮归来！正始昆只。","田邑千畛，人阜昌只。","美冒众流，德泽章只。","先威后文，善美明只。","魂乎归来！赏罚当只。","名声若日，照四海只。","德誉配天，万民理只。","北至幽陵，南交阯只。","西薄羊肠，东穷海只。","魂乎归来！尚贤士只。","发政献行，禁苛暴只。","举杰压陛，诛讥罢只。","直赢在位，近禹麾只。","豪杰执政，流泽施只。","魂乎来归！国家为只。","雄雄赫赫，天德明只。","三公穆穆，登降堂只。","诸侯毕极，立九卿只。","昭质既设，大侯张只。","执弓挟矢，揖辞让只。","魂乎来归！尚三王只。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-27","tags":[]},{"id":"poem-d96a7b8389d4fe12ae6279f3","title":"奉和圣制送张说上集贤学士赐宴","author":"刘升","dynasty":"唐","verses":["图书应明主，策府宴嘉宾。","台曜临东壁，干光自北辰。","网罗穷象系，述作究天人。","圣酒千钟洽，仙厨百味陈。","成山徒可仰，涉海讵知津。","幸逢文教盛，还覩颂声新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4595908c-a166-442c-ac0a-afee0f0defdd","tags":[]},{"id":"poem-d971bd2b47948a6820b97771","title":"发新安后途中寄卢中丞二首 一","author":"赵嘏","dynasty":"唐","verses":["楼上风流庾使君，笙歌曾醉此中闻。","目前已是陵阳路，回首丛山满眼云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-742eb740-805e-4e63-bd6c-a86eb5bb661b","tags":[]},{"id":"poem-d974e8b39192b78553763a11","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)休焦，所许前问，侍枕之私，敢惜微眇。","(生)既如此，却又推三阻四怎么？(旦)怕仁人累德，娶而不告，朋友相嘲。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2984","tags":[]},{"id":"poem-d97b8fc6da63cab2641e43e5","title":"郊庙歌辞 周宗庙乐舞辞 肃雍舞","author":"不详","dynasty":"唐","verses":["周道载兴，象日之明。","万邦咸庆，百谷用成。","於穆圣祖，祗荐鸿名。","祀于庙社，陈其牺牲。","进旅退旅，皇武之形。","一倡三叹，朱弦之声。","以妥以侑，既和且平。","至诚潜达，介福攸宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-40427e69-1d6a-4d07-8428-f3cbda689880","tags":[]},{"id":"poem-d989d884f7f4d77ccd024ba4","title":"平日游园常策筇杖秋来发箧复出貂褥二物皆景仁所贶覩物思人斐然成诗","author":"司马光","dynasty":"宋","verses":["筇杖携已久，貂褥展犹新。","渐染岷山雪，拂除京国尘。","危扶醉归路，稳称病来身。","赖此斋中物，时如见故人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1b3cebce-8bd5-491f-b22a-bbe59b0b09da","tags":[]},{"id":"poem-d98ed30d425ea4a09b0849af","title":"次韵感旧","author":"赵文","dynasty":"宋","verses":["人间岁月如江波，欢乐苦少哀情多。","千曲箜篌弹不尽，公无渡河公渡河。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-44028bf3-aa9c-427e-8425-f6f61c1e0cff","tags":[]},{"id":"poem-d99d9b6cd5813fd5ad33b9aa","title":"龙安院","author":"陈岩","dynasty":"宋","verses":["蔓草丛生伴棘薪，古藤直上绕松身。","寺前寺后清幽处，山鸟飞来不避人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-db3d4a29-aee8-4f97-9b36-9c897c79cbf3","tags":[]},{"id":"poem-d99e0d5c5ed4180f94876903","title":"林下书怀寄建州李频员外","author":"曹松","dynasty":"唐","verses":["一从诸事嬾，海上迹宜沉。","吾道不当路，鄙人甘入林。","云垂方觅鹤，月湿始收琴。","水石南州好，谁陪刻骨吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6fbbbd13-6d29-4128-952c-96d45e353fc8","tags":[]},{"id":"poem-d9a047199b0f05c5ffbe736d","title":"郊庙歌辞 仪坤庙乐章 寿和","author":"徐坚","dynasty":"唐","verses":["於穆清庙，肃雍严祀。","合福受厘，介以繁[祉]。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d95c1136-9489-4d8b-a72e-22d1b0e7f1a3","tags":[]},{"id":"poem-d9a73c284c2f6b7135b69bbf","title":"一翦梅·红映阑干绿映阶","author":"李石","dynasty":"宋","verses":["红映阑干绿映阶。","闲闷闲愁，独自徘徊。","天涯消息几时归，别后无书有梦来。","后院棠梨昨夜开。","雨急风忙次第催。","罗衣消瘦却春寒，莫管红英，一任苍苔。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-262","tags":[]},{"id":"poem-d9a97a9ed17ea89791caa1c2","title":"狂题十八首 一","author":"司空图","dynasty":"唐","verses":["莫恨艰危日日多，时情其奈幸门何。","貔貅睡稳蛟龙渴，犹把烧残朽铁磨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a3c2f0e7-0940-4496-a686-ef586df5e2ad","tags":[]},{"id":"poem-d9b2b28567f77d57731f6f9b","title":"三年冬大礼五首 一","author":"曹唐","dynasty":"唐","verses":["皇帝斋心洁素诚，自朝真祖报升平。","华山秋草多归马，沧海寒波绝洗兵。","银箭水残河势断，玉炉烟尽日华生。","千官整肃三天夜，劒佩初闻入太清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2693a9bf-a0ba-44bd-b308-4de0b9925856","tags":[]},{"id":"poem-d9c267e2300e39fc3cf05594","title":"远闻本郡行春到旧山二首 二","author":"朱景玄","dynasty":"唐","verses":["清风借响松筠外，画隼停晖水石间。","定掩溪名在图传，共知轩盖此登攀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a889c4f3-38d2-45f9-8c7a-29931e72d844","tags":[]},{"id":"poem-d9c41f5f6282eb60036d1f75","title":"小游仙诗九十八首 八十九","author":"曹唐","dynasty":"唐","verses":["东溟两度作尘飞，一万年来会面稀。","千树棃花百壶酒，共君论饮莫论诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-47674538-d3e4-4ba4-8476-0de4c576dcee","tags":[]},{"id":"poem-d9cc565de3e2785fb9de98dd","title":"越女词","author":"鲍溶","dynasty":"唐","verses":["越女芙蓉妆，浣纱清浅水。","忽惊春心晓，不敢思君子。","君子纵我思，宁来浣溪里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d5febff1-aa0d-482a-91ce-09733762f19d","tags":[]},{"id":"poem-d9cd11ab11184ae11372f0d0","title":"清平乐·愁肠欲断","author":"孙光宪","dynasty":"五代","verses":["愁肠欲断，正是青春半。","连理分枝鸾失伴，又是一场离散。","掩镜无语眉低，思随芳草萋萋。","凭仗东风吹梦，与郎终日东西。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-19","tags":[]},{"id":"poem-d9d5bb81aa9101a04b9aec6b","title":"闲来","author":"司马光","dynasty":"宋","verses":["闲来观万物，在处可逍遥。","鱼为贪钩得，蛾因赴火焦。","碧梧饥𬸚𬸦，白粒饱鹪鹩。","带索谁家子，行歌复采樵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-530c0d98-d63d-4330-99f4-6ce1ed9f07be","tags":[]},{"id":"poem-d9d60ecf8a7ff83109542363","title":"杂曲歌辞 婆罗门","author":"杨敬述进","dynasty":"唐","verses":["回乐峰前沙似雪，受降城外月如霜。","不知何处吹芦管？一夜征人尽望乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f1320c1f-949a-4cbe-ad23-4806878632c5","tags":["思念","战争","冬天","唐诗三百首","边塞","七言绝句","月亮"]},{"id":"poem-d9d9a53e2c16fe714822cbf0","title":"后庭花破子·玉树后庭前","author":"李煜","dynasty":"五代","verses":["玉树后庭前，瑶草妆镜边。","去年花不老，今年月又圆。","莫教偏，和月和花，大教长少年。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-40","tags":[]},{"id":"poem-d9e0e154ae4f1add0a43719c","title":"月下笛·万里孤云","author":"张炎","dynasty":"宋","verses":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-261","tags":["宋词三百首"]},{"id":"poem-d9e7bf2ed65437138d86be9b","title":"韦使君宅海榴咏","author":"皇甫曾","dynasty":"唐","verses":["淮阳卧理有清风，腊月榴花带雪红。","闭阁寂寥常对此，江湖心在数枝中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-84fccfc1-60e4-4e70-a963-bcd0224c80c9","tags":[]},{"id":"poem-d9e912fa1510b8ab735c9039","title":"调笑・调笑令·南土","author":"洪适","dynasty":"宋","verses":["南土。","贤铜虎。","黄木湾头腾好语。","骑羊执穗神仙五。","拭目摩肩争睹。","无双治行今犹古。","嘉瑞流传乐府。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-644","tags":[]},{"id":"poem-d9eadad9919e51490ed8de27","title":"南歌子·似带如丝柳","author":"温庭筠","dynasty":"唐","verses":["似带如丝柳，团酥握雪花。","帘卷玉钩斜，九衢尘欲暮，逐香车。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-38","tags":[]},{"id":"poem-d9ed5776f10003fcda993af6","title":"思远人·红叶黄花秋意晚","author":"晏几道","dynasty":"宋","verses":["红叶黄花秋意晚，千里念行客。","飞云过尽，归鸿无信，何处寄书得。","泪弹不尽临窗滴。","就砚旋研墨。","渐写到别来，此情深处，红笺为无色。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-35","tags":["宋词三百首"]},{"id":"poem-d9f4c1463a9146231d25d54a","title":"咏史诗 夷门","author":"胡曾","dynasty":"唐","verses":["六龙冉冉骤朝昏，魏国贤才杳不存。","唯有侯嬴在时月，夜来空自照夷门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5b5d6e31-5080-4f0c-a097-8c52005bf87c","tags":[]},{"id":"poem-da019fd4a472a85fb28c0781","title":"维摩赞","author":"释了惠","dynasty":"宋","verses":["示疾毗耶方丈，文殊亦难近傍。","看来无药可医，只是忌口为上。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4623ee83-a707-49e9-8ba8-72b24985fe61","tags":[]},{"id":"poem-da077b23a2596b0c88933e6a","title":"杨柳枝寿杯词十八首 十","author":"司空图","dynasty":"唐","verses":["游人莫叹易凋衰，长乐荣枯自有期。","看取明年春意动，更于何处最先知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3e107fb7-ce0e-4935-9f20-39f90087ed35","tags":[]},{"id":"poem-da12142d7a212f205b08afdf","title":"河传·心情老懒","author":"黄庭坚","dynasty":"宋","verses":["心情老懒。","对歌对舞，犹是当时眼。","巧笑靓妆，近我衰容华鬓。","似扶著、卖卜算。","思量好个当年见。","催酒催更，只怕归期短。","饮散灯稀，背锁落花深院。","好杀人、天不管。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-815","tags":[]},{"id":"poem-da178a1a0c09e16481f3cb61","title":"玉环山","author":"王十朋","dynasty":"宋","verses":["清有濯缨水，白有漱齿石。","悠哉水石间，宦情聊自适。","朝焉游其南，暮焉游其北。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5ae7829f-a94a-4fa9-8e3e-76e557da3594","tags":[]},{"id":"poem-da190f6991710fe09bbd0a6b","title":"西施咏","author":"王维","dynasty":"唐","verses":["艳色天下重，西施宁久微。","朝仍越溪女，暮作吴宫妃。","贱日岂殊众，贵来方悟稀。","邀人傅香粉，不自著罗衣。","君宠益娇态，君怜无是非。","当时浣纱伴，莫得同车归。","持谢邻家子，效颦安可希。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4d6f83e9-8232-4db1-903e-f9e619df5ecb","tags":["唐诗三百首","隋・唐・五代","五言古诗","怀古","写人","怀才不遇"]},{"id":"poem-da1b18fd6ed56d417355bf7c","title":"归舟三绝  其二","author":"王柏","dynasty":"宋","verses":["波声拍枕不成眠，拥被推篷月尚圆。","霜下夜深人正悄，数声飞雁度林颠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8cd3c7cd-ce9c-4c57-b34f-4ae8096c89a5","tags":[]},{"id":"poem-da1eabb5a95c88bd46af42d5","title":"江城子·宝津楼下柳阴重","author":"张纲","dynasty":"宋","verses":["宝津楼下柳阴重。","画桥东。","戏鱼龙。","闻喜当时，开宴盛仪容。","遥想新年寻故事，扶醉帽，夕阳中。","可怜衰鬓飒霜丛。","借酡红。","遣愁浓。","梦入长安，惊起送飞鸿。","直下青冥休避路，九万里，看抟风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-656","tags":[]},{"id":"poem-da23cc9c6315430092fabc57","title":"淳熙四年二月既望静江守臣张某奉诏劝农于郊乃作熙熙阳春之诗二十四章章四句以示父老俾告于其乡之人而歌之  其一","author":"张栻","dynasty":"宋","verses":["熙熙阳春，既发既舒。","翼翼南亩，是展是图。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-bfad9e1f-9a26-4086-ab55-482e9d8e6cfc","tags":[]},{"id":"poem-da2d53343f06096f95342c4e","title":"落花","author":"朱淑贞","dynasty":"宋","verses":["连理枝头花正开，妒花风雨便相催。","愿教青帝常为主，莫遣纷纷点翠苔。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-落花","tags":[]},{"id":"poem-da306ad134d915972c6f87aa","title":"题独孤处士村居","author":"薛逢","dynasty":"唐","verses":["江上园卢荆作扉，男驱耕犊妇鸣机。","林峦当户茑萝暗，桑柘绕村姜芋肥。","几亩稻田还谓业，两间茆舍亦言归。","何如一被风尘染，到老云云相是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4655da21-244c-4436-8345-7373bba1c0f1","tags":[]},{"id":"poem-da3a774438af7a6c81cb8622","title":"韩碑","author":"李商隐","dynasty":"唐","verses":["元和天子神武姿，彼何人哉轩与羲。","誓将上雪列圣耻，坐法宫中朝四夷。","淮西有贼五十载，封狼生䝙䝙生罴。","不据山河据平地，长戈利矛日可麾。","帝得圣相相曰度，贼斫不死神扶持。","腰悬相印作都统，阴风惨澹天王旗。","愬武古通作牙爪，仪曹外郎载笔随。","行军司马智且勇，十四万众犹虎貔。","入蔡缚贼献太庙，功无与让恩不訾。","帝曰汝度功第一，汝从事愈宜为辞。","愈拜稽首蹈且舞，金石刻画臣能为。","古者世称大手笔，此事不系于职司。","当仁自古有不让，言讫屡颔天子颐。","公退斋戒坐小阁，濡染大笔何淋漓。","点窜尧典舜典字，涂改清庙生民诗。","文成破体书在纸，清晨再拜铺丹墀。","表曰臣愈昧死上，咏神圣功书之碑。","碑高三丈字如斗，负以灵鼇蟠以螭。","句奇语重喻者少，谗之天子言其私。","长绳百尺拽碑倒，麤砂大石相磨治。","公之斯文若元气，先时已入人肝脾。","汤盘孔鼎有述作，今无其器存其辞。","呜呼圣皇及圣相，相与烜赫流淳熙。","公之斯文不示后，曷与三五相攀追。","愿书万本诵万过，口角流沫右手胝。","传之七十有二代，以为封禅玉检明堂基。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0d2c5fba-d350-4c3f-b55e-72a491a84df6","tags":["唐诗三百首","叙事","七言古诗","咏史"]},{"id":"poem-da4004fef6b941822f9179ab","title":"村市","author":"宋伯仁","dynasty":"宋","verses":["山暗风屯雨，溪浑水浴沙。","小桥通古寺，疎柳纳残鸦。","苜蓿重沽酒，芝麻旋点茶。","愿人长似旧，岁岁插桃花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-308550eb-faac-4000-80e8-dabf7fb866fd","tags":[]},{"id":"poem-da4266b9f04d0c0cc15ef8f2","title":"敝笱","author":"佚名","dynasty":"先秦","verses":["敝笱在梁，其鱼鲂鳏。齐子归止，其从如云。","敝笱在梁，其鱼鲂𫚈。齐子归止，其从如雨。","敝笱在梁，其鱼唯唯。齐子归止，其从如水。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-103","tags":[]},{"id":"poem-da4457733d1fbad9694afae5","title":"点绛唇·春遇瑶池","author":"仲殊","dynasty":"宋","verses":["春遇瑶池，长空飞下残英片。","素光围练。","寒透笙歌院。","莫把寿阳，妆信传书箭。","掩香面。","汉宫寻遍。","月里还相见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-880","tags":[]},{"id":"poem-da46e5515a41cfbf9cb187e8","title":"惜双双・惜分飞·皎镜平湖三十里","author":"贺铸","dynasty":"宋","verses":["皎镜平湖三十里。","碧玉山围四际。","莲荡香风里。","彩鸳鸯觉双飞起。","明月多情随舵尾。","偏照空床翠被。","回首笙歌地。","醉更衣处长相记。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-845","tags":[]},{"id":"poem-da4761bda0c1458db56af23f","title":"闻胡邦衡改知泉州复用前韵","author":"王十朋","dynasty":"宋","verses":["上念温陵为择人，知公名节世无隣。","犯颜合在论思地，起废聊为岳牧臣。","缪政居前诮穅秕，刚肠别久转车轮。","天教我辈簪重盍，只恐留中拱帝宸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1b170353-3379-4a0b-b9fe-bc4e8d6d6555","tags":[]},{"id":"poem-da52829072a14fbb227682fe","title":"祭汾阴乐章","author":"韩思复","dynasty":"唐","verses":["大乐和畅，殷荐明神。","一降通感，八变必臻。","有求斯应，无德不亲。","降灵醉止，休征万人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ab10b8da-25cd-4c86-bc72-39ea5106adaf","tags":[]},{"id":"poem-da55cb66d5df278bed130d25","title":"寒塘","author":"赵嘏","dynasty":"唐","verses":["晓发梳临水，寒塘坐见秋。","乡心正无限，一雁度南楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e1064aa9-4b66-4a1a-9f95-8675b1141fb7","tags":[]},{"id":"poem-da5832caa195a41f7ad638f3","title":"忒忒令","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生、旦)许多时缘何未归？眼巴。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1929","tags":[]},{"id":"poem-da5db135f27e79d6c62719b4","title":"八归·芳莲坠粉","author":"姜夔","dynasty":"宋","verses":["芳莲坠粉，蔬桐吹绿，庭院暗雨乍歇。","无端抱影销魂处，还见筱墙萤暗，藓阶蛩切。","送客重寻西去路，问水面、琵琶谁拨。","最可惜、一片江山，总付与啼。","长恨相从未款，而今何事，又对西风离别。","渚寒烟淡，棹移人远，缥缈行舟如叶。","想文君望久，倚竹愁生步罗袜。","归来后、翠尊双饮，下了珠帘，玲珑闲看月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-131","tags":["宋词三百首"]},{"id":"poem-da6652af20ce3f74a2f2b6a4","title":"汾沮洳","author":"佚名","dynasty":"先秦","verses":["彼汾沮洳，言采其莫。彼其之子，美无度。美无度，殊异乎公路。","彼汾一方，言采其桑。彼其之子，美如英。美如英，殊异乎公行。","彼汾一曲，言采其藚。彼其之子，美如玉。美如玉，殊异乎公族。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-107","tags":[]},{"id":"poem-da6a640f05e8f8044a23ac68","title":"答绍彭书来论晋帖误字","author":"米芾","dynasty":"宋","verses":["何必识难字，辛苦笑扬雄。","自古写字人，用字或不通。","要之皆一戏，不当问拙工。","意足我自足，放笔一戏空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-21f36497-bfe4-4214-bd15-f8d5277cb26b","tags":[]},{"id":"poem-da7a5ba10ca24731de8a7ae7","title":"和元帅书记萧郎中观习水师","author":"徐铉","dynasty":"宋","verses":["元帅楼船出治兵，落星山外火旗明。","千帆日助江陵势，万里风驰下濑声。","杀气晓严波上鹢，凯歌遥骇海边鲸。","仲宣一作从军咏，回顾儒衣自不平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-73b672f1-500e-46c4-aa37-fca016022910","tags":[]},{"id":"poem-da83e71c9d3c0e314b014c44","title":"醉落魄","author":"无名氏《张协状元》","dynasty":"元","verses":["冤家做作好直恁，把心不定。","(生)张协去心不安稳，不见归来，寻你那脸节病。","(旦唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2582","tags":[]},{"id":"poem-da88bc490d8a5e9db1c9421c","title":"代崇徽公主意","author":"李山甫","dynasty":"唐","verses":["金钗坠地鬓堆云，自别朝阳帝岂闻。","遣妾一身安社稷，不知何处用将军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1a7353dc-27dd-4f11-a384-4cec7a407e29","tags":[]},{"id":"poem-da89c0aa9b7d140b554028a9","title":"送叶主簿楚州应钱帅之招","author":"陈造","dynasty":"宋","verses":["汉庭用少余，无策销外侮。","充国七十翁，胜算定樽俎。","夫君谭西北，万里真目睹。","诸将失投机，遽岂一二数。","形势可聚米，君王未借箸。","江湖五十年，帝阍严九虎。","后生不更事，儿戏议边圉。","圆方殊枘凿，寂默忍羁旅。","平生干霄气，百吞不一吐。","白眼阅流俗，闭口避尔汝。","山阳文武资，干国今吉甫。","清啸临筹边，志已无骄虏。","经年虚代舍，须君作谋主。","心嗤区区郑，缓不省之武。","盍思度外意，径略纸上语。","山阳吾未识，仿佛梦眉宇。","断知磊落人，众弃能独取。","一巵劝临分，三叹欲轻举。","抒君胸中奇，定作商应羽。","还应访隠沦，道我听鸡舞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-41f2b029-966b-4c50-ac0a-32a18ce4aa66","tags":[]},{"id":"poem-da8a41293c7afbb12989b5f8","title":"次韵章时可","author":"陈造","dynasty":"宋","verses":["般门难呈拙，仰屋方自咎。","诗肩卓两峰，因君笑今又。","袖手非不佳，拜赐良独厚。","翩翩王公孙，肝肺衷绘绣。","向来传新作，价欲擅文囿。","妙语再堕前，吟玩忘昏昼。","江涛骇澎湃，风竹聆疎瘦。","足我学古心，如饮得美酎。","气无寒郊寒，派续后山后。","采采葩华林，群芳酿孤茂。","错刀合琼瑶，内索慙寡陋。","肯如周人朴，唾去不一嗅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e5f366eb-fb00-4231-a50a-9509a08b4f3d","tags":[]},{"id":"poem-da8c7f86509d2826184547c0","title":"题画鹰","author":"华镇","dynasty":"宋","verses":["高飞远走可人情，上蔡东青旧有名。","谁在华堂餍鼎俎，自甘平野掠柴荆。","心忧狐兔纷难尽，眼看豺狼恣不平。","莫倚丝绳金縼美，弓藏鸟尽汝须惊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7087ea18-f4f1-47e7-9db1-ff1ac5ad6ab3","tags":[]},{"id":"poem-da9c6a87b46b050fdf5006b2","title":"临江仙·槛竹敲风初破睡","author":"史浩","dynasty":"宋","verses":["槛竹敲风初破睡，楚台梦雨精神。","背屏斜映小腰身。","山明双翦水，香满一钗云。","炉袅金丝帘窣地，绮窗秋静无尘。","半钩春笋带湘筠。","兰亭初写就，愁杀卫夫人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-78","tags":[]},{"id":"poem-da9ca9e32cdacab36b8d0f94","title":"送成都韦丞还蜀","author":"李端","dynasty":"唐","verses":["蜀门云树合，高栈有猿愁。","驱传加新命，之官向旧游。","晨装逢酒雨，夜梦见刀州。","远别长相忆，当年莫滞留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-fd046c72-5c26-4565-b0cc-044e954feda6","tags":[]},{"id":"poem-daa07cd0104b7742d9032580","title":"秋风引","author":"刘禹锡","dynasty":"唐","verses":["何处秋风至，萧萧送雁群。","朝来入庭树，孤客最先闻。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋風引","tags":[]},{"id":"poem-daa2eae1a052576a8e913c69","title":"菩萨蛮·画屏重叠巫阳翠","author":"牛峤","dynasty":"五代","verses":["画屏重叠巫阳翠，楚神尚有行云意。","朝暮几般心，向他情漫深。","风流今古隔，虚作瞿塘客。","山月照山花，梦回灯影斜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-17","tags":[]},{"id":"poem-daa7a0e50f7ec33723d05479","title":"行宫","author":"元稹","dynasty":"唐","verses":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-02943f6d-2c91-4d9c-9690-247eab9ae3ec","tags":["隋・唐・五代","怀古","宫怨","唐诗三百首","五言绝句"]},{"id":"poem-daa8f35ff8d858e9bf711c46","title":"度关山","author":"李端","dynasty":"唐","verses":["雁塞日初晴，狐关雪复平。","危楼缘广漠，古窦傍长城。","拂剑金星出，弯弧玉羽鸣。","谁知系虏者，贾谊是书生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a83f524c-ef82-4bb8-a14b-f3360e7b5d2a","tags":[]},{"id":"poem-daa9be74820e0bcc9bdee327","title":"春日晋祠同声会集得疎字韵","author":"李益","dynasty":"唐","verses":["风壤瞻唐本，山祠阅晋余。","水亭开帟幕，岩榭引簪裾。","地绿苔犹少，林黄柳尚疎。","菱苕生皎镜，金碧照澄虚。","翰苑声何旧，宾筵醉止初。","中州有辽雁，好为系边书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-344bb72a-dec5-427d-b523-bc60d71bc8ee","tags":[]},{"id":"poem-daab1b9d405f197c1425034b","title":"送金华赵宰二首  其一","author":"王柏","dynasty":"宋","verses":["弦歌声里一瓢安，士友催诗送长官。","律己十分无可议，爱民一念未尝寒。","更知耐事如公少，留取清名作样看。","百姓越疆归令问，恩流职外此尤难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c86a3fd7-c6d2-4288-9d6a-b9c7bbccfd51","tags":[]},{"id":"poem-daad710f30e8cd6c3dce8c47","title":"石州引・石州慢·薄雨初寒","author":"贺铸","dynasty":"宋","verses":["薄雨初寒，斜照弄晴，春意空阔。","长亭柳色缠黄，远客一枝先折。","烟横水际，映带几点归鸦，东风销尽龙沙雪。","还记初关来，恰而今时节。","将发。","画楼芳酒，红泪清歌，顿成清别。","已是经年，杳杳音尘多绝。","欲知方寸，共有几许清愁，芭蕉不展丁香结。","枉望断天涯，两厌厌风月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-104","tags":["宋词三百首"]},{"id":"poem-daae51ad6a676f1e10a30603","title":"富贵曲","author":"李咸用","dynasty":"唐","verses":["画藻雕山金碧彩，鸳鸯曡翠眠晴霭。","编珠影里醉春庭，团红片下攒歌黛。","革咽丝烦欢不改，缴绛垂缇忽如晦。","活花起舞夜春来，蜡焰煌煌天日在。","雪暖瑶杯凤髓融，红拖象筯猩唇细。","空中汉转星移盖，火城拥出随朝会。","车如雷兮马如龙，鬼神辟易不敢害。","冠峩剑重锵环珮，步入天门相真宰。","开口长为爵禄筌，回眸便是公卿罪。","珍珠索得龙宫贫，膏腴刮下苍生背。","九野干戈指著心，威福满拳犹未快。","我闻周公贵为天子弟，富有半四海。","蔑有骄奢贻后悔，红锦障收。","珊瑚树碎，至今笑石崇王恺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5767a5df-ea11-4c46-bf8c-6ab84e0f9f15","tags":[]},{"id":"poem-dab0204835a15601a1ee9b24","title":"却渡西陵别越中父老","author":"李绅","dynasty":"唐","verses":["海潮晚上江风急，津吏篙师语默齐。","倾手奉觞看故老，拥流争拜见孩提。","慙非杜母临襄岘，自鄙朱翁别会稽。","渐举云帆烟水阔，杳然凫雁各东西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5052c292-7fcd-4d89-90f8-f585cba128be","tags":[]},{"id":"poem-dab84f48f914d62102f49a91","title":"送雍郢州","author":"李端","dynasty":"唐","verses":["厌郎思出守，遂领汉东军。","望月逢殷浩，缘江送范云。","城闲烟草遍，浦逈雪林分。","谁伴楼中宿，吟诗估客闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-61b2b15c-601a-479b-a00a-f4dcd6f88b13","tags":[]},{"id":"poem-dabcb760c862067cfa0dce57","title":"河传·太平天子","author":"孙光宪","dynasty":"五代","verses":["太平天子，等闲游戏，疏河千里。","柳如丝，偎倚绿波春水，长淮风不起。","如花殿脚三千女，争云雨，何处留人住？","锦帆风，烟际江，烧空，魂迷大业中。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-46","tags":[]},{"id":"poem-dacdda2f806337fe40880f74","title":"走马川行奉送出师西征","author":"岑参","dynasty":"唐","verses":["君不见走马川行雪海边，平沙莽莽黄入天。","轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。","匈奴草黄马正肥，金山西见烟尘飞。","汉家大将西出师，将军金甲夜不脱。","半夜军行戈相拨，风头如刀面如割。","马毛带雪汗气蒸，五花连钱旋作冰。","幕中草檄砚水凝，虏骑闻之应胆慑。","料知短兵不敢接，车师西门伫献捷。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f5e021d7-ea56-4341-947c-8fd024018e1c","tags":["唐诗三百首","写马","写风","送别","初中古诗","七言古诗","九年级下册(课外)","风","边塞","赞美","马","将士"]},{"id":"poem-dad53fd24d643bd8974a2ed3","title":"阮郎归·去年今日落花时","author":"欧阳修","dynasty":"宋","verses":["去年今日落花时。","依前又见伊。","淡匀双脸浅匀眉。","青衫透玉肌。","才会面，便相思。","相思无尽期。","这回相见好相知。","相知已是迟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-798","tags":[]},{"id":"poem-dae1138e7a7dd8b5f3d48ddf","title":"赠王道士","author":"于邺","dynasty":"唐","verses":["日日市朝路，何时无苦辛。","不随丹灶客，终作白头人。","浮世度千载，桃源方一春。","归来华表上，应笑北邙尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e8ac4222-39b9-48fe-9538-8556c1b08b37","tags":[]},{"id":"poem-dae1da360374db8d057d755e","title":"踏莎行·映竹幽妍","author":"毛滂","dynasty":"宋","verses":["映竹幽妍，临池娟靓。","芳苞先暖香初娠。","南枝微弄雪精神，东君早寄春音信。","奔月仙标，乘烟远韵。","玉台粉点和酥凝。","从来清瘦可禁寒，为谁早把霞衣褪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-758","tags":[]},{"id":"poem-dae1ec77fda7b864dfd1e24a","title":"别耿都尉","author":"高适","dynasty":"唐","verses":["四十能学劒，时人无此心。","如何耿夫子，感激投知音。","翩翩白马来，二月青草深。","别易小千里，兴酣倾百金。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c6491c82-16cc-417f-bc8d-4cf938aa4ed4","tags":[]},{"id":"poem-dae74028e9a23a77015b3598","title":"江南柳·隋堤远","author":"张先","dynasty":"宋","verses":["隋堤远，波急路尘轻。","今古柳桥多送别，见人分袂亦愁生。","何况自关情。","斜照后，新月上西城。","城上楼高重倚望，愿身能似月亭亭。","千里伴君行。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-281","tags":[]},{"id":"poem-daf3ffc6729e4b4a8392397e","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["贱人你自为娟妓，哥哥把伊提携。","岂知杨花怎拘，作事更不存理。","(和同前)(旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8689","tags":[]},{"id":"poem-daf4a18fc9e93ce88a41f0c1","title":"胡捣练","author":"徐田臣《杀狗记》","dynasty":"元","verses":["江水远，恨悠悠，教人羞耻向谁求？枉自腹藏千古事，但趁一江清水向东流。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1749","tags":[]},{"id":"poem-dafa9f3483ede8755575cb81","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)曾寄书回，深恨孙郎故改易。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8346","tags":[]},{"id":"poem-db0207f3896ab4a3927444a1","title":"宫词  其四一","author":"张公庠","dynasty":"宋","verses":["过腊愆阳陇麦低，御封香合奉精祈。","君王晓入凝华殿，远近楼台看雪飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d2706557-fba3-4682-b765-3c2e077cd513","tags":[]},{"id":"poem-db02b034705416effabedd30","title":"秋宿青龙禅阁","author":"李洞","dynasty":"唐","verses":["前山不可望，暮色渐沉规。","日转须弥北，蟾来渤海西。","风铃乱僧语，霜枿欠猿啼。","阁外千家月，分明见里迷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-070c44d2-e6e2-4040-83c2-5f6c18123917","tags":[]},{"id":"poem-db06c96268b8f823840130d9","title":"意难忘","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["绿鬓仙郎，懒拈花弄柳，劝酒持觞。","长颦知有恨，何事苦思量？(生唱)些介事，恼人肠。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5169","tags":[]},{"id":"poem-db0780fd5b394d4201be6491","title":"更漏子·玉狻猊","author":"毛滂","dynasty":"宋","verses":["玉狻猊，金叶暖。","馥馥香云不断。","长下著，绣帘重。","怕随花信风。","傍蔷薇，摇露点。","衣润得香长远。","双枕凤，一衾鸾。","柳烟花雾间。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-820","tags":[]},{"id":"poem-db08a81a7ba8fa8d38280c1f","title":"发新安后途中寄卢中丞二首 二","author":"赵嘏","dynasty":"唐","verses":["晚树萧萧促织愁，风帘似水满床秋。","千山不碍笙歌月，谁伴羊公上夜楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-cec64e0f-fe44-4486-9a72-5f2918eca31d","tags":[]},{"id":"poem-db09a5a5046b996f0b129f08","title":"雪","author":"李洞","dynasty":"唐","verses":["迢迢来极塞，连阙谓风吹。","禅客呵金锡，征人擘冻旗。","细填虫穴满，重压鹤巢欹。","有影晴飘野，无声夜落池。","正繁秦甸暖，渐厚楚宫饥。","冻挹分泉涩，光凝二阁痴。","踏遗兰署迹，听起石门思。","用表丰年瑞，无令埽玉墀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-513d8869-5c70-4ca0-9c0f-ff0a0c3931b1","tags":[]},{"id":"poem-db0db789077e4edb1c2fd33f","title":"九日侍宴应制","author":"崔国辅","dynasty":"唐","verses":["运偶千年圣，时传九日神。","尧樽列钟鼓，汉阙辟钩陈。","金箓三清降，琼筵五老巡。","始惊兰佩出，复咏柏梁新。","云鴈楼前晚，霜花酒里春。","欢娱无限极，书劒太平人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-81588847-ae7f-410b-91b7-56441ccdb81a","tags":[]},{"id":"poem-db15429838cae54172e94ace","title":"杨柳枝词","author":"崔道融","dynasty":"唐","verses":["雾撚烟搓一索春，年年长似染来新。","应须唤作风流线，系得东西南北人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9c5a93c9-8486-4e2c-a496-e9512e5ea123","tags":[]},{"id":"poem-db17b92e4c8484003a8a2e82","title":"摸鱼儿·更能消、几番风雨","author":"辛弃疾","dynasty":"宋","verses":["更能消、几番风雨。","匆匆春又归去。","惜春长恨花开早，何况落红无数。","春且住。","见说道、天涯芳草迷归路。","怨春不语。","算只有殷勤，画檐珠网，尽日惹飞絮。","长门事，准拟佳期又误。","蛾眉曾有人妒。","千金纵买相如赋，脉脉此情谁诉。","君莫舞。","君不见、玉环飞燕皆尘土。","闲愁最苦。","休去倚危楼，斜阳正在，烟柳断肠处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-207","tags":["宋词三百首"]},{"id":"poem-db196b6f2326aaf91492763a","title":"黄鹂绕碧树·双阙笼嘉气","author":"周邦彦","dynasty":"宋","verses":["双阙笼嘉气，寒威日晚，岁华将暮。","小院闲庭，对寒梅照雪，淡烟凝素。","忍当迅景，动无限、伤春情绪。","犹赖是、上苑风光渐好，芳容将煦。","草荚兰芽渐吐。","且寻芳、更休思虑。","这浮世、甚驱驰利禄，奔竞尘土。","纵有魏珠照乘，未买得流年住。","争如盛饮流霞，醉偎琼树。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-449","tags":[]},{"id":"poem-db2035a7cdbbe35a47da313b","title":"郊庙歌辞 明堂乐章 肃和","author":"褚亮","dynasty":"唐","verses":["象天御宇，乘时布政。","严配申虔，宗禋展敬。","罇罍盈列，树羽交映。","玉币通诚，祚隆皇圣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-50b7a780-78ba-4e4c-acee-b185d8f6571f","tags":[]},{"id":"poem-db2325e932b8e82a728ded46","title":"送友人入蜀","author":"李白","dynasty":"唐","verses":["见说蚕丛路，崎岖不易行。","山从人面起，云傍马头生。","芳树笼秦栈，春流绕蜀城。","升沈应已定，不必问君平。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送友人入蜀","tags":[]},{"id":"poem-db26eef0bd9b8a55a7fbb633","title":"南乡子·沙月静","author":"李珣","dynasty":"五代","verses":["沙月静，水烟轻，芰荷香里夜船行。","绿鬟红脸谁家女？","遥相顾，缓唱棹歌极浦去。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-31","tags":[]},{"id":"poem-db2860590c2fda1fd37e8d6a","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["比似我做了亏心台馆客，到不如守义终身田舍郎。","白头吟记得不曾忘，绿鬓妇何故在他方？书，我只为你其中有女颜如玉，却教我撇却糟糠妻下堂。","还思想，休休，毕竟是文章误我，我误妻房。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5219","tags":[]},{"id":"poem-db464821102a88ddac559b92","title":"次韵林茂南参谋观阅水战之作","author":"李纲","dynasty":"宋","verses":["习战楼船章水滨，机轮运转若无人。","旌麾耀日惊飞鹭，金鼓翻波跃锦鳞。","四坐纵观聊举白，一阳潜动欲回春。","羽书正报淮淝捷，想见胪传设九宾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2a6d19ae-4fc3-4142-887b-8fba1c9ef1c7","tags":[]},{"id":"poem-db4d299df7f5efaf30163384","title":"诗品二十四则 高古","author":"司空图","dynasty":"唐","verses":["畸人乘真，手把芙蓉。","泛彼浩劫，窅然空纵。","月出东斗，好风相从。","太华夜碧，人闻清钟。","虚伫神素，脱然畦封。","黄唐在独，落落玄宗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-96104c85-c9df-4967-8fd3-a33d09cd71cb","tags":[]},{"id":"poem-db529cf91fa3b1f09f537b66","title":"踏莎行·人问山中","author":"张抡","dynasty":"宋","verses":["人问山中，因何无暑。","山堂恰在山深处。","藤阴满地走龙蛇，泉声万壑鸣风雨。","且弄青松，休挥白羽。","相逢况有烟霞侣。","长天一任火云飞，夜凉踏月相将去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-938","tags":[]},{"id":"poem-db58fa05196b2ad89598b880","title":"却望无锡芙蓉湖 三","author":"李绅","dynasty":"唐","verses":["逐波云影参差远，背日岚光隐见深。","犹似望中连海树，月生湖上是山阴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-26c9b6ee-4ca2-4ecb-b153-4ac1415090a1","tags":[]},{"id":"poem-db616bd46b1c7ee28c1b9b7e","title":"和立斋抱膝吟三章  其二","author":"王柏","dynasty":"宋","verses":["谁卧草庐中，能耑一壑风。","当时天地闭，豪杰不相容。","中原河岳应如旧，虎豹出没非人有。","祗今不是龙卧时，自是君才掣君肘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-fd0fb2fb-66f9-455a-81a7-5ba831a55bd3","tags":[]},{"id":"poem-db63653be789d10e9196ce3f","title":"同熊少府题卢主簿茅斋","author":"高适","dynasty":"唐","verses":["虚院野情在，茅斋秋兴存。","孝廉趋下位，才子出高门。","乃继幽人静，能令学者尊。","江山归谢客，神鬼下刘根。","阶树时攀折，窗书任讨论。","自堪成独往，何必武陵源。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f61c206e-7b6f-4c94-ad64-bfb843c5269d","tags":[]},{"id":"poem-db76549ce71fb1ce5c1a9938","title":"哭刘言史","author":"孟郊","dynasty":"唐","verses":["诗人业孤峭，饿死良已多。","相悲与相笑，累累其奈何。","精异刘言史，诗肠倾珠河。","取次抱置之，飞过东溟波。","可惜大国谣，飘为四夷歌。","常于众中会，颜色两切[磋]。","今日果成死，葬襄之洛河。","洛岸远相吊，洒泪双滂沱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-346f34e0-5943-44bb-b4ec-3370c166a187","tags":[]},{"id":"poem-db88f4cb14049dbf40d669a4","title":"端康之间地名越城五山秀峙有蜿蜒飞跃之状山有五龙庙当秦时神媪临江五龙从之游没葬山上庙祀至今灵响甚著乡人以风雨候龙之归因作送迎辞五绝句以遗之  其二","author":"李纲","dynasty":"宋","verses":["五山秀峙若飞腾，下有澄潭百丈清。","不用燃犀窥秘怪，从来神理恶分明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-11766c03-0273-416e-8292-fdc82af4b5dd","tags":[]},{"id":"poem-db94d053254778acb567ca77","title":"醉落魄・一斛珠·虚窗透月","author":"张抡","dynasty":"宋","verses":["虚窗透月。","寒莎败壁蛩吟切。","沈沈永漏灯明灭。","只为愁人，不为道人设。","愁人对此成愁绝。","道人终是心如铁。","一般景趣情怀别。","笛里西风，吹下满庭叶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-919","tags":[]},{"id":"poem-dba120a7e030eb499290e2b2","title":"城南即事  其一","author":"张栻","dynasty":"宋","verses":["活泉细引忽盈沟，自遶书斋堦堦流。","添得眼前无限思，石桥竹坞共清幽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5535b8ae-cc64-4292-9d2a-700c9b7b6839","tags":[]},{"id":"poem-dba1fea469124815bdf76ba8","title":"十月之交","author":"佚名","dynasty":"先秦","verses":["十月之交，朔月辛卯。日有食之，亦孔之丑。彼月而微，此日而微；今此下民，亦孔之哀。","日月告凶，不用其行。四国无政，不用其良。彼月而食，则维其常；此日而食，于何不臧。","烨烨震电，不宁不令。百川沸腾，山冢崒崩。高岸为谷，深谷为陵。哀今之人，胡惨莫惩？","皇父卿士，番维司徒，家伯维宰，仲允膳夫，棸子内史，蹶维趣马，楀维师氏。醘妻煽方处。","抑此皇父，岂曰不时？胡为我作，不即我谋？彻我墙屋，田卒污莱。曰予不戕，礼则然矣。","皇父孔圣，作都于向。择三有事，亶侯多藏。不慭遗一老，俾守我王。择有车马，以居徂向。","黾勉从事，不敢告劳。无罪无辜，谗口嚣嚣。下民之孽，匪降自天。噂沓背憎，职竞由人。","悠悠我里，亦孔之痗。四方有羡，我独居忧。民莫不逸，我独不敢休。天命不彻，我不敢效我友自逸。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-192","tags":[]},{"id":"poem-dbb18da343ac9cb52ef7b547","title":"生查子·惆怅彩云飞","author":"纳兰性德","dynasty":"清","verses":["惆怅彩云飞，碧落知何许。","不见合欢花，空倚相思树。","总是别时情，那待分明语。","判得最长宵，数尽厌厌雨。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-12","tags":[]},{"id":"poem-dbbb9768870a9ee9b09f4356","title":"浣溪沙·微绽樱桃一颗红","author":"吕渭老","dynasty":"宋","verses":["微绽樱桃一颗红。","断肠声里唱玲珑。","轻罗小扇掩酥胸。","惹鬓蛛丝新有喜，窥窗月彩旧相从。","清宵一醉许谁同。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-82","tags":[]},{"id":"poem-dbbe314654a5e73b8001199b","title":"永明山居诗（六十九首） 五十一","author":"延寿","dynasty":"唐","verses":["名利梯媒事已忘，唯凭拙直定行藏。","探玄休炼长生药，助道时抄歇食方。","溪汲古痕山雨涨，树摧残枿野风狂。","一言欲寄休回首。","尘路如今事正忙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c60a659e-dbeb-4e98-b71b-4b00954ba932","tags":[]},{"id":"poem-dbd493066e3e1c853263424b","title":"昊天有成命","author":"佚名","dynasty":"先秦","verses":["昊天有成命，二后受之。成王不敢康，夙夜基命宥密。于缉熙！单厥心，四其靖之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-270","tags":[]},{"id":"poem-dbd4aef40327b348507c9f35","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(贴)天赐这姻缘，喜他们也姓钱，同临所作宛转。","明日动船，开洋过浅，愿一阵好风，急去登福建。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8220","tags":[]},{"id":"poem-dbde413f832e1c326b09f7e5","title":"自淇涉黄河途中作十三首 十一","author":"高适","dynasty":"唐","verses":["我行倦风湍，辍棹将问津。","空传歌瓠子，感慨独愁人。","孟夏桑叶肥，秾阴夹长津。","蚕农有时节，田野无闲人。","临水狎渔樵，望山怀隐沦。","谁能去京洛，顦顇对风尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c501f17a-230a-49b5-833c-5889a4e9bc85","tags":["黄河"]},{"id":"poem-dbe1cd561a3e8bc6f13538fb","title":"宫词  其三","author":"张公庠","dynasty":"宋","verses":["秘阁新开别殿西，玉蟾蜍对玉狻猊。","奏书未惬君王意，内省夫人看御批。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5ca4a8c6-3c06-4c7f-a83b-3da0c9e11605","tags":[]},{"id":"poem-dbe927e862e94a7b3c12bf74","title":"临江仙","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(老旦上)客梦悠悠鸡唤醒，窗前尚有残灯。","(生、末上)揽衣披枕自评论，今日飘零，何日安宁？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8257","tags":[]},{"id":"poem-dbf611744a88b31ba72012ab","title":"满江红·回首吾庐","author":"毛并","dynasty":"宋","verses":["回首吾庐，思归去、石溪樵谷。","临玩有、门前流水，乱松疏竹。","幽草春馀荒井迳，鸣禽日在窥墙屋。","但等闲、凭几看南山，云相逐。","家酿美，招邻曲。","朝饭饱，随耕牧。","况东皋二顷，岁时都足。","鳞阁功名身外事，墙阴不驻流光促。","更休论、一枕梦中惊，黄粱熟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-623","tags":[]},{"id":"poem-dbf68f11327e430498638f69","title":"逍遥四章呈钦之尧夫  其一","author":"司马光","dynasty":"宋","verses":["结髪读经史，疲精非一朝。","于今成濩落，所幸得逍遥。","不韪狂心息，难平客气消。","巢林易为足，窃敢比鹪鹩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7aaf8e6f-6930-42cf-9679-084056dc5ddc","tags":[]},{"id":"poem-dbf8b35a57daf11fc3b8933f","title":"偈颂三十首  其三○","author":"释印肃","dynasty":"宋","verses":["出家无易事，了道亦非难。","各自要努力，如人担上山。","累劫负偿命，此生莫等闲。","遇时若不顺，展转落雠关。","佛与人方便，度人及登山。","布身而填险，为众代艰难。","荷担如来者，莫道不当番。","汝逆和尚顺，明朝报愈艰。","汝见有福者，拥从物如山。","在处皆如是，因修得世间。","若争人我相，不如快下山。","若酬自己债，岂用学烧丹。","相逢无别有，动不是风幡。","前后都还却，独坐大雄山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4dc2000e-4eed-4759-b13b-f56bd05ebcc2","tags":[]},{"id":"poem-dbf8f1acfca1dd8904a85f99","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)三娘本娇媚，三娘本娇媚，父母多年纪。","生长村庄勤纺织，攻针指。","愿降慈祥，父母双全喜。","(合前)生偷鸡介。","众惊介。","(外)神道灵异，把我祭物，金龙爪去了。","(末)这方见太公来得志诚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8813","tags":[]},{"id":"poem-dbff1910fe58e08ce8e1537b","title":"戏程紫霄登华山偶颠仆（题拟）","author":"宇文翰","dynasty":"唐","verses":["不知上得不得，且怪悬之又悬。","（见《类说》卷四十一《北梦琐言》。","紫霄，原作「子霄」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e2c09dc6-734b-44ab-8e39-f44fb64e7a8b","tags":[]},{"id":"poem-dc241e936ef7c759e3e8752a","title":"宫中曲二首 二","author":"徐凝","dynasty":"唐","verses":["身轻入宠尽恩私，腰细偏能舞柘枝。","一日新妆抛旧样，六宫争画黑烟眉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1b91577e-ed76-4404-9954-05bb4de06515","tags":[]},{"id":"poem-dc297fae2aa3d24857df6104","title":"渔家傲·十月小春梅蕊绽","author":"欧阳修","dynasty":"宋","verses":["十月小春梅蕊绽。","红炉画阁新妆遍。","锦帐美人贪睡暖。","羞起晚。","玉壶一夜冰澌满。","楼上四垂帘不卷。","天寒山色偏宜远。","风急雁行吹字断。","红日短。","江天雪意云撩乱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-647","tags":[]},{"id":"poem-dc3402505c34fc9e724ceb66","title":"一○六","author":"王梵志","dynasty":"唐","verses":["家有梵志诗，生死免入狱。","不论有益事，且得耳根熟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d3e3a577-c1d8-4f77-9b56-67c1196876bd","tags":[]},{"id":"poem-dc34f19e76c8557003ba5dd3","title":"奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制","author":"王维","dynasty":"唐","verses":["渭水自萦秦塞曲，黄山旧遶汉宫斜。","銮舆迥出千门柳，阁道廻看上苑花。","云里帝城双凤阙，雨中春树万人家。","为乘阳气行时令，不是宸游玩物华。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ce71032a-c075-492c-9554-51eb080348a5","tags":["唐诗三百首","黄山","应制","七言律诗"]},{"id":"poem-dc3535eeaa8a38dafd6a01af","title":"咏史诗 渑池","author":"胡曾","dynasty":"唐","verses":["日照荒城芳草新，相如曾此挫强秦。","能令百二山河主，便作樽前击缶人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b7c039e6-77cd-4db3-b27f-4e32c830b822","tags":[]},{"id":"poem-dc3e886bed8501210c889b96","title":"桂枝香·酦醅初熟","author":"黄裳","dynasty":"宋","verses":["酦醅初熟。","竞看九日、西风弄寒菊。","姝子新妆，向晓淡黄千簇。","清香闹处君须住，掺盈头、醉乡相逐。","马台欢笑，龙山纵逸，佳话重绪。","共尽日、登临未足。","更休问明年，浮世荣辱。","难得良辰，鬓发见秋尤绿。","且邀月照金尊上，近人寒、如对飞瀑。","宴归还趁人来，茱萸佩垂红玉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-616","tags":[]},{"id":"poem-dc4134e85bc0d8a70ee35ec3","title":"题泽翁小卷  其七","author":"王柏","dynasty":"宋","verses":["野渡人归处，纵横八九家。","晚来寒力健，风飐酒帘斜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e65a9647-b7d3-4920-8d86-a0f9c06c3aa5","tags":[]},{"id":"poem-dc42f5139d3f99fffcae3dc8","title":"归去来·一夜狂风雨","author":"柳永","dynasty":"宋","verses":["一夜狂风雨。","花英坠、碎红无数。","垂杨漫结黄金缕。","尽春残、萦不住。","蝶稀蜂散知何处。","𣨼尊酒、转添愁绪。","多情不惯相思苦。","休惆怅、好归去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-249","tags":[]},{"id":"poem-dc489e6cef37e91e14baec05","title":"元日鸿庆宫朝拜二十韵","author":"苏颂","dynasty":"宋","verses":["上国房心次，仙都太紫微。","璧门开倣雉，金阙立如翚。","昔圣躬三祀，乘时动六飞。","奠圭涡曲已，鸣跸涣阳归。","孚号兴王泽，尊名象日畿。","经营原庙制，虔巩上天威。","祖系崇轩鼎，宗祊奉汉衣。","豫游恩甚盛，谒款礼无违。","却顾和鸾迹，咸嗟岁序非。","璇源流永永，尧德冠巍巍。","我后遵鸿烈，声明极范围。","乾坤扶宝历，日月拱琳扉。","朝会元正始，班联内著依。","叙官风宪肃，就列羽仪辉。","北面鸾分党，东隅斗转机。","寒销冰玉砌，风绕大龙旗。","瑞色花藏绿，欢声雾散霏。","未竣真馆集，遥仰帝阳晞。","至治尤遐邈，先猷重发挥。","邦人徒望幸，延首向端闱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-c2dcb8b7-eb12-4dd5-a170-77ada543eb29","tags":[]},{"id":"poem-dc48de5e5b687b2e01a20366","title":"赠商山东于岭僧","author":"李廓","dynasty":"唐","verses":["商岭东西路欲分，两间茅屋一溪云。","师言耳重知师意，人是人非不欲闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f954ad69-29d1-47de-975a-5b0118730758","tags":[]},{"id":"poem-dc496f333a031733a052520c","title":"山石","author":"韩愈","dynasty":"唐","verses":["山石荦确行径微，黄昏到寺蝙蝠飞。","升堂坐阶新雨足，芭蕉叶大支子肥。","僧言古壁佛画好，以火来照所见稀。","铺床拂席置羹饭，疎粝亦足饱我饥。","夜深静卧百虫绝，清月出岭光入扉。","天明独去无道路，出入高下穷烟霏。","山红涧碧纷烂漫，时见松枥皆十围。","当流赤足蹋涧石，水声激激风吹衣。","人生如此自可乐，岂必局束为人鞿。","嗟哉吾党二三子，安得至老不更归。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e73e2743-3752-4ba3-938a-fb59cd3965ee","tags":["唐诗三百首","纪游","写景","抒情","七言古诗"]},{"id":"poem-dc4a16b460afe209bbdd62fb","title":"归闲诗二十韵","author":"丁儒","dynasty":"唐","verses":["漳北遥开郡，泉南久罢屯。","归寻初旅寓，喜作旧乡邻。","好鸟鸣簷竹，村黎爱幕臣。","土音今听惯，民俗始知淳。","烽火无传警，江山已净尘。","天开一岁暖，花发四时春。","杂卉三冬绿，嘉禾两度新。","俚歌声靡曼，秫酒味温醇。","锦苑来丹荔，清波出素鳞。","芭蕉金剖润，龙眼玉生津。","蜜取花间[露]（液），柑藏树上珍。","醉宜𫉄蔗沥，睡稳木棉[茵]（温）。","茉莉香篱落，榕阴浃里𬮱。","雪霜偏避地，风景独推闽。","辞国来诸属，于兹缔六亲。","追随情语好，问餽[岁]（几）时频。","相访朝和夕，浑忘越与秦。","功成在炎域，事定有闲身。","词赋聊酬和，才名任隐沦。","呼童多种植，长是此方人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-784de624-96ba-47ce-afe3-a10681eef3dd","tags":[]},{"id":"poem-dc4b1eae2b4414405dfbbb82","title":"既醉","author":"佚名","dynasty":"先秦","verses":["既醉以酒，既饱以德。君子万年，介尔景福。","既醉以酒，尔肴既将。君子万年，介尔昭明。","昭明有融，高朗令终，令终有俶。公尸嘉告。","其告维何？笾豆静嘉。朋友攸摄，摄以威仪。","威仪孔时，君子有孝子。孝子不匮，永锡尔类。","其类维何？室家之壶。君子万年，永锡祚胤。","其胤维何？天被尔禄。君子万年，景命有仆。","其仆维何？厘尔女士。厘尔女士，从以孙子。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-246","tags":[]},{"id":"poem-dc589e13a25abdb574e46951","title":"离骚","author":"屈原","dynasty":"先秦","verses":["帝高阳之苗裔兮，朕皇考曰伯庸。","摄提贞于孟陬兮，惟庚寅吾以降。","皇览揆余初度兮，肇锡余以嘉名：名余曰正则兮，字余曰灵均。","纷吾既有此内美兮，又重之以修能。","扈江离与辟芷兮，纫秋兰以为佩。","汨余若将不及兮，恐年岁之不吾与。","朝搴阰之木兰兮，夕揽洲之宿莽。","日月忽其不淹兮，春与秋其代序。","惟草木之零落兮，恐美人之迟暮。","不抚壮而弃秽兮，何不改乎此度？","乘骐骥以驰骋兮，来吾道夫先路！","昔三后之纯粹兮，固众芳之所在。","杂申椒与菌桂兮，岂惟纫夫蕙茝！","彼尧、舜之耿介兮，既遵道而得路。","何桀纣之猖披兮，夫惟捷径以窘步。","惟夫党人之偷乐兮，路幽昧以险隘。","岂余身之殚殃兮，恐皇舆之败绩！","忽奔走以先后兮，及前王之踵武。","荃不查余之中情兮，反信谗而齌怒。","余固知謇謇之为患兮，忍而不能舍也。","指九天以为正兮，夫惟灵修之故也。","曰黄昏以为期兮，羌中道而改路！","初既与余成言兮，后悔遁而有他。","余既不难夫离别兮，伤灵修之数化。","余既滋兰之九畹兮，又树蕙之百亩。","畦留夷与揭车兮，杂杜衡与芳芷。","冀枝叶之峻茂兮，愿俟时乎吾将刈。","虽萎绝其亦何伤兮，哀众芳之芜秽。","众皆竞进以贪婪兮，凭不厌乎求索。","羌内恕己以量人兮，各兴心而嫉妒。","忽驰骛以追逐兮，非余心之所急。","老冉冉其将至兮，恐修名之不立。","朝饮木兰之坠露兮，夕餐秋菊之落英。","苟余情其信姱以练要兮，长顑颔亦何伤。","掔木根以结茞兮，贯薜荔之落蕊。","矫菌桂以纫蕙兮，索胡绳之𫄥𫄥。","謇吾法夫前修兮，非世俗之所服。","虽不周于今之人兮，愿依彭咸之遗则。","长太息以掩涕兮，哀民生之多艰。","余虽好修姱以鞿羁兮，謇朝谇而夕替。","既替余以蕙𬙋兮，又申之以揽茝。","亦余心之所善兮，虽九死其犹未悔。","怨灵修之浩荡兮，终不察夫民心。","众女嫉余之蛾眉兮，谣诼谓余以善淫。","固时俗之工巧兮，偭规矩而改错。","背绳墨以追曲兮，竞周容以为度。","忳郁邑余侘傺兮，吾独穷困乎此时也。","宁溘死以流亡兮，余不忍为此态也。","鸷鸟之不群兮，自前世而固然。","何方圜之能周兮，夫孰异道而相安？","屈心而抑志兮，忍尤而攘诟。","伏清白以死直兮，固前圣之所厚。","悔相道之不察兮，延伫乎吾将反。","回朕车以复路兮，及行迷之未远。","步余马于兰皋兮，驰椒丘且焉止息。","进不入以离尤兮，退将复修吾初服。","制芰荷以为衣兮，集芙蓉以为裳。","不吾知其亦已兮，苟余情其信芳。","高余冠之岌岌兮，长余佩之陆离。","芳与泽其杂糅兮，唯昭质其犹未亏。","忽反顾以游目兮，将往观乎四荒。","佩缤纷其繁饰兮，芳菲菲其弥章。","民生各有所乐兮，余独好修以为常。","虽体解吾犹未变兮，岂余心之可惩。","女媭之婵媛兮，申申其詈予，曰：鲧婞直以亡身兮，终然夭乎羽之野。","汝何博謇而好修兮，纷独有此姱节？","薋菉葹以盈室兮，判独离而不服。","众不可户说兮，孰云察余之中情？","世并举而好朋兮，夫何茕独而不予听？","依前圣以节中兮，喟凭心而历兹。","济沅、湘以南征兮，就重华而敶词：启《九辩》与《九歌》兮，夏康娱以自纵。","不顾难以图后兮，五子用失乎家衖。","羿淫游以佚畋兮，又好射夫封狐。","固乱流其鲜终兮，浞又贪夫厥家。","浇身被服强圉兮，纵欲而不忍。","日康娱而自忘兮，厥首用夫颠陨。","夏桀之常违兮，乃遂焉而逢殃。","后辛之菹醢兮，殷宗用而不长。","汤、禹俨而祗敬兮，周论道而莫差。","举贤才而授能兮，循绳墨而不颇。","皇天无私阿兮，览民德焉错辅。","夫维圣哲以茂行兮，苟得用此下土。","瞻前而顾后兮，相观民之计极。","夫孰非义而可用兮？","孰非善而可服？","阽余身而危死兮，览余初其犹未悔。","不量凿而正枘兮，固前修以菹醢。","曾歔欷余郁邑兮，哀朕时之不当。","揽茹蕙以掩涕兮，沾余襟之浪浪。","跪敷衽以陈辞兮，耿吾既得此中正。","驷玉虬以桀鹥兮，溘埃风余上征。","朝发轫于苍梧兮，夕余至乎县圃。","欲少留此灵琐兮，日忽忽其将暮。","吾令羲和弭节兮，望崦嵫而勿迫。","路漫漫其修远兮，吾将上下而求索。","饮余马于咸池兮，总余辔乎扶桑。","折若木以拂日兮，聊逍遥以相羊。","前望舒使先驱兮，后飞廉使奔属。","鸾皇为余先戒兮，雷师告余以未具。","吾令凤鸟飞腾兮，继之以日夜。","飘风屯其相离兮，帅云霓而来御。","纷总总其离合兮，斑陆离其上下。","吾令帝阍开关兮，倚阊阖而望予。","时暧暧其将罢兮，结幽兰而延伫。","世溷浊而不分兮，好蔽美而嫉妒。","朝吾将济于白水兮，登阆风而绁马。","忽反顾以流涕兮，哀高丘之无女。","溘吾游此春宫兮，折琼枝以继佩。","及荣华之未落兮，相下女之可诒。","吾令丰隆乘云兮，求宓妃之所在。","解佩𬙋以结言兮，吾令謇修以为理。","纷总总其离合兮，忽纬繣其难迁。","夕归次于穷石兮，朝濯发乎洧盘。","保厥美以骄傲兮，日康娱以淫游。","虽信美而无礼兮，来违弃而改求。","览相观于四极兮，周流乎天余乃下。","望瑶台之偃蹇兮，见有娀之佚女。","吾令鸩为媒兮，鸩告余以不好。","雄鸠之鸣逝兮，余犹恶其佻巧。","心犹豫而狐疑兮，欲自适而不可。","凤皇既受诒兮，恐高辛之先我。","欲远集而无所止兮，聊浮游以逍遥。","及少康之未家兮，留有虞之二姚。","理弱而媒拙兮，恐导言之不固。","世溷浊而嫉贤兮，好蔽美而称恶。","闺中既以邃远兮，哲王又不寤。","怀朕情而不发兮，余焉能忍而与此终古？","索琼茅以筳篿兮，命灵氛为余占之。","曰：两美其必合兮，孰信修而慕之？","思九州之博大兮，岂惟是其有女？」","曰：勉远逝而无狐疑兮，孰求美而释女？","何所独无芳草兮，尔何怀乎故宇？」","世幽昧以昡曜兮，孰云察余之善恶？","民好恶其不同兮，惟此党人其独异！","户服艾以盈要兮，谓幽兰其不可佩。","览察草木其犹未得兮，岂珵美之能当？","苏粪壤以充祎兮，谓申椒其不芳。","欲从灵氛之吉占兮，心犹豫而狐疑。","巫咸将夕降兮，怀椒糈而要之。","百神翳其备降兮，九疑缤其并迎。","皇剡剡其扬灵兮，告余以吉故。","曰：勉升降以上下兮，求矩矱之所同。","汤、禹俨而求合兮，挚、咎繇而能调。","苟中情其好修兮，又何必用夫行媒？","说操筑于傅岩兮，武丁用而不疑。","吕望之鼓刀兮，遭周文而得举。","宁戚之讴歌兮，齐桓闻以该辅。","及年岁之未晏兮，时亦犹其未央。","恐鹈𫛞之先鸣兮，使夫百草为之不芳。","何琼佩之偃蹇兮，众𫉁然而蔽之。","惟此党人之不谅兮，恐嫉妒而折之。","时缤纷其变易兮，又何可以淹留？","兰芷变而不芳兮，荃蕙化而为茅。","何昔日之芳草兮，今直为此萧艾也？","岂其有他故兮，莫好修之害也！","余以兰为可恃兮，羌无实而容长。","委厥美以从俗兮，苟得列乎众芳。","椒专佞以慢慆兮，榝又欲充夫佩帏。","既干进而务入兮，又何芳之能祗？","固时俗之流从兮，又孰能无变化？","览椒兰其若兹兮，又况揭车与江离？","惟兹佩之可贵兮，委厥美而历兹。","芳菲菲而难亏兮，芬至今犹未沬。","和调度以自娱兮，聊浮游而求女。","及余饰之方壮兮，周流观乎上下。","灵氛既告余以吉占兮，历吉日乎吾将行。","折琼枝以为羞兮，精琼爢以为粻。","为余驾飞龙兮，杂瑶象以为车。","何离心之可同兮？","吾将远逝以自疏。","邅吾道夫昆仑兮，路修远以周流。","扬云霓之晻蔼兮，鸣玉鸾之啾啾。","朝发轫于天津兮，夕余至乎西极。","凤皇翼其承旗兮，高翱翔之翼翼。","忽吾行此流沙兮，遵赤水而容与。","麾蛟龙使梁津兮，诏西皇使涉予。","路修远以多艰兮，腾众车使径待。","路不周以左转兮，指西海以为期。","屯余车其千乘兮，齐玉轪而并驰。","驾八龙之婉婉兮，载云旗之委蛇。","抑志而弭节兮，神高驰之邈邈。","奏《九歌》而舞《韶》兮，聊假日以偷乐。","陟升皇之赫戏兮，忽临睨夫旧乡。","仆夫悲余马怀兮，蜷局顾而不行。","乱曰：已矣哉！国无人莫我知兮，又何怀乎故都！","既莫足与为美政兮，吾将从彭咸之所居！"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-0","tags":[]},{"id":"poem-dc74f4b8dc6d0062896fad22","title":"子云故居","author":"刘望之","dynasty":"宋","verses":["杀却王章爱孔光，举朝谁复说兴亡。","未能免俗歌新美，岂不怀归念楚狂。","斗酒只今犹寂寞，小池无旧已荒凉。","秋风细雨催人去，似恐徘徊费感伤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-fed94140-f78e-428e-8462-dc5c1f1e86a9","tags":[]},{"id":"poem-dc76122efc68d79311e80d13","title":"乱后途中","author":"李山甫","dynasty":"唐","verses":["乱离寻故园，朝市不如村。","恸哭翻无泪，颠狂觉少魂。","诸侯贪割据，群盗恣幷吞。","为问登坛者，何年答汉恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-4a224e8b-7580-49b4-9906-caef628be9c0","tags":[]},{"id":"poem-dc8b222f58842ed8d2332636","title":"宫词  其六九","author":"张公庠","dynasty":"宋","verses":["圣主忧勤览万机，日高前殿步舆归。","太官进膳传呼速，御合翩翩入禁扉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-51fb674c-28fc-45bb-8306-fbf7df3f4da9","tags":[]},{"id":"poem-dc946ee7f91e7bf63e1d991d","title":"游上雪窦诗","author":"延寿","dynasty":"唐","verses":["下雪窦游上雪窦，过云峰后望云峰。","如趋仙府经三岛，似入天门彻九重。","无日不飞丹顶鹤，有时忽起隐潭龙。","祇因奉诏西归去，此境何由得再逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-38fcb454-becf-4284-9824-1c899f8ee917","tags":[]},{"id":"poem-dc97045f4e4ff79d18d24c29","title":"表弟万大年宿郡斋为鼠蚊蚤所苦夜不安寝目为三害某辄申造物之意谕之以诗","author":"王十朋","dynasty":"宋","verses":["万子游清源，颇爱风物好。","胡为官舍中，害有蚊鼠蚤。","啮衣恣掀翻，聒耳倦挥扫。","跳虫从何来，出没席与藁。","中夜不安寝，披衣起呼皂。","禽鼠磔其尸，驱蚊熏以草。","炽炭烘衾禂，虮虱亦俱薧。","三害稍稍除，高眠起忘早。","我时寝凝香，清梦到穹昊。","仙官为我言，必大有家宝。","乃翁多隠德，子籍在蓬岛。","天将成就之，故以此相恼。","要令坐达旦，万卷饱探讨。","毋如老外兄，不学首空皓。","彼虫类最多，生育自洪造。","尽杀则伤仁，兼容幸宽抱。","万子闻我言，往往笑绝倒。","燔庐相参元，失马福塞老。","宴安生鸩毒，疾患资寿考。","三害不必除，君言近乎道。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d1a1c7b4-af8b-4017-b8ae-f8f9b15da024","tags":[]},{"id":"poem-dca2c551588fbff4451c550e","title":"玉楼春·晴景融融春色浅","author":"杜安世","dynasty":"宋","verses":["晴景融融春色浅。","落尽梅花千万片。","小池冰解水纹生，消息未闻梁上燕。","楼倚轻寒风力软。","目断孤云天自远。","又还依旧去年时，寂寞病容人怪见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-891","tags":[]},{"id":"poem-dca42f606056d72a941d6b40","title":"郊庙歌辞 享惠昭太子庙乐章 请神","author":"归登","dynasty":"唐","verses":["嘉荐既陈，祀事孔明。","闲歌在堂，万舞在庭。","外则尽物，内则尽诚。","凤笙如闻，歌其洁精。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8f1bdb64-597c-4b05-ba77-8ed259edfb60","tags":[]},{"id":"poem-dca579b8d91cc77ce3f5692a","title":"句","author":"朱景玄","dynasty":"唐","verses":["塞鸿先秋去，边草入夏生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-79e71022-c513-4c45-91af-bcebd74af647","tags":[]},{"id":"poem-dcade768ad2c16970ecefa18","title":"题张于潜画轴五首  其五","author":"释居简","dynasty":"宋","verses":["飚生凉腋策茶勋，欲御刚风度海云。","任是蓬莱更高处，叫苍生苦有谁闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-47ef1cc1-730d-4776-83bc-93b2b82aec13","tags":[]},{"id":"poem-dcb297aea5b18f4859d7ca67","title":"题清溪鬼谷先生旧居","author":"李涉","dynasty":"唐","verses":["翠壁开天池，青崖列云树。","冰容不可状，杳若清河雾。","常闻先生教，指示秦仪路。","二子才不同，逞词过尺度。","偶因从吏役，远到冥栖处。","松月想旧山，烟霞了如故。","未遑炼金鼎，日觉容光暮。","万虑随境生，何由返真素。","寂寞天籁息，清逈鸟声曙。","回首望重重，无期挹风驭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1f4f0ec0-15a2-405b-a0c0-b29328a660a1","tags":[]},{"id":"poem-dcb958b27d3d9a217cbbebc3","title":"将入关行次湘阴","author":"曹松","dynasty":"唐","verses":["背顾秦城在何处，图书作伴过湘东。","神鵶乱噪黄陵近，候鴈斜沈梦泽空。","打桨天连晴水白，烧田云隔夜山红。","也知渐老岩栖稳，争奈文闱有至公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-73de3c4b-708f-4016-a4d9-e1b5423f8f20","tags":[]},{"id":"poem-dcba374f6780b6cec9c689da","title":"送净道人","author":"徐铉","dynasty":"宋","verses":["北阜与西山，前期梦寐间。","羡师乘兴去，应拟此生闲。","乔木人谁在，鲈鱼我未还。","归心寄秋水，东去日潺潺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-32bd5779-9286-4a68-9ba7-6184aeb1ca47","tags":[]},{"id":"poem-dcbc577c41e24ae3d1555a00","title":"高阳台·接叶巢莺","author":"张炎","dynasty":"宋","verses":["接叶巢莺，平波卷絮，断桥斜日归船。","能几番游，看花又是明年。","东风且伴蔷薇住，到蔷薇、春已堪怜。","更凄然。","万绿西泠，一抹荒烟。","当年燕子知何处，但苔深韦曲，草暗斜川。","见说新愁，如今也到鸥边。","无心再续笙歌梦，掩重门、浅醉闲眠。","莫开帘。","怕见飞花，怕听啼鹃。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-53","tags":["宋词三百首"]},{"id":"poem-dcbea4b5f4acbd0a103563f3","title":"杂诗三首 二","author":"王维","dynasty":"唐","verses":["君自故乡来，应知故乡事。","来日绮窗前，寒梅着花未。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4c7205af-d1e8-48ed-8220-fe095418b95a","tags":["唐诗三百首","景中情","写景","思亲","梅花","思乡","五言绝句"]},{"id":"poem-dcc056df346f64dbe97dc3e1","title":"劝学偈","author":"令参","dynasty":"唐","verses":["苦哉甚苦哉，波里觅干灰。","劝君收取手，正与摩时俫。","（以上三首均见《祖堂集》卷十。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6bfd92e8-6763-45f1-8e97-27dbd7dc1706","tags":[]},{"id":"poem-dcd19c582cbaaaaa53039813","title":"二犯渔家傲","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["思量，幼读文章，论事亲为子也须要成模样。","真情未讲，怎知道吃尽多磨障？被亲强来赴选场，被君强官为议郎，被婚强效鸾凰。","三被强衷肠说与谁行？埋冤难禁这两厢，这壁厢道咱是个不撑达害羞的乔相识，那壁厢道咱是个不睹是负心的薄幸郎。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5115","tags":[]},{"id":"poem-dcd3c2e847092bbf6359ab58","title":"自叹拙","author":"李山甫","dynasty":"唐","verses":["自怜心计拙，欲语更悲辛。","世乱僮欺主，年衰鬼弄人。","镜中颜欲老，江上业长贫。","不是刘公乐，何由变此身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f2429d5e-f507-4138-b954-911a00a831a1","tags":[]},{"id":"poem-dcd8bcaae7242a7af1126e2c","title":"御书阁","author":"王十朋","dynasty":"宋","verses":["黄龙溪上祥云覆，紫帽山头瑞气蒙。","俗眼惊传佛光现，不知宸翰在山中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2e0ebdea-3fe0-457b-914c-d8217cd99f63","tags":[]},{"id":"poem-dcdc5f3d816f3df4fb16fde8","title":"墨梅  其二","author":"释居简","dynasty":"宋","verses":["楚楚仙裳澹染缁，耐寒宜瘦不宜肥。","莫言无子调商鼎，卿相当年有黑衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1e54297f-0e31-4a94-b976-d0cf3fc2ca96","tags":[]},{"id":"poem-dcdd2529991fce96fed01d30","title":"奉陪张燕公登南楼","author":"尹懋","dynasty":"唐","verses":["君子每垂眷，江山共流眄。","水远林外明，岩近雾中见。","终日西北望，何处是京县。","屡登高春台，徒使泪如霰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7b07f0f8-43aa-46a2-9169-ead6a5715141","tags":[]},{"id":"poem-dce756f0cfae480356064316","title":"送人宰邑","author":"裴说","dynasty":"唐","verses":["官小任还重，命官难偶然。","皇恩轻一邑，赤子病三年。","瘦马稀飡粟，羸童不识钱。","如君清苦节，到处有人传。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-93a2ad3c-7dc2-46bc-8114-d7d5e4b27c76","tags":[]},{"id":"poem-dce9e4725761993d01488698","title":"九歌·云中君","author":"屈原","dynasty":"先秦","verses":["浴兰汤兮沐芳，华采衣兮若英。","灵连蜷兮既留，烂昭昭兮未央。","謇将憺兮寿宫，与日月兮齐光。","龙驾兮帝服，聊翱游兮周章。","灵皇皇兮既降，猋远举兮云中。","览冀洲兮有余，横四海兮焉穷。","思夫君兮太息，极劳心兮忡忡。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-2","tags":[]},{"id":"poem-dcf3d985fec96ab7d0662f75","title":"再归松溪旧居宿西林","author":"徐凝","dynasty":"唐","verses":["五粒松深溪水清，众山摇落月偏明。","西林静夜重来宿，暗记人家犬吠声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2c9dbda3-46ee-418f-9d1f-1b8a8cb01978","tags":[]},{"id":"poem-dd146a5bb753ef5e1792893e","title":"夜游湖","author":"无名氏《张协状元》","dynasty":"元","verses":["合那官员有万千。","(丑)甚人才先来拜见。","(净)小子名为柳屯田。","(合)揖揖两个通寒暄。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2714","tags":[]},{"id":"poem-dd14842161e2e01f75a67b8b","title":"和咏廨署有樱桃","author":"孙逖","dynasty":"唐","verses":["上林天禁里，芳树有红樱。","江国今来见，君门春意生。","香从花绶转，色绕佩珠明。","海鸟衔初实，吴姬扫落英。","切将稀取贵，羞与众同荣。","为此堪攀折，芳蹊处处成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d1f7ade0-dbf7-42e2-8245-410f06dcb360","tags":[]},{"id":"poem-dd1c8587bbd82402f22b1ed9","title":"浣溪沙·腊日银罂翠管新","author":"张纲","dynasty":"宋","verses":["腊日银罂翠管新。","潘舆迎腊庆生辰。","卷帘花簇锦堂春。","百和宝薰笼瑞雾，一声珠唱驻行云。","流霞深劝莫辞频。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-651","tags":[]},{"id":"poem-dd1e1540bccaacb643d10a56","title":"哭皇天","author":"杨景贤","dynasty":"元","verses":["师父听得叫罢询详细，弟子见言绝说个就里。","师父，你不知，这座山是花果山。","山下有一洞，是紫云罗洞。","洞中有一魔君，号曰\"通天大圣\"，恼得三界圣贤，不得安宁。","李天王、那叱太子、眉山大圣收得，待杀坏他来。","观音佛抄化他，压在山下，等师父宋，着与师父护法。","他凡心不退，不可用他。","(唐僧云)小僧弘誓如深海，如何不救他？(山神唱)你道你弘誓如海深，那胡孙气力与天齐。","这厮瞒神唬鬼，铜筋铁骨，火眼金睛。","偷玉皇仙酒，盗老子金丹。","他去那众魔君中占第一，他是骊山老母兄弟，巫支祗是姊妹。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10318","tags":[]},{"id":"poem-dd2216881edfaf86caac8740","title":"谢陶谷饷鸭卵及莲枝一捻红（题拟）","author":"符昭远","dynasty":"唐","verses":["圣朝初出赤志翁，丑杖旁扶赤志翁。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6c761a18-876e-4552-9e8e-5e8bbd021b6f","tags":[]},{"id":"poem-dd39b72361fb9802207cef54","title":"车舝","author":"佚名","dynasty":"先秦","verses":["间关车之舝兮，思娈季女逝兮。匪饥匪渴，德音来括。虽无好友？式燕且喜。","依彼平林，有集维鷮。辰彼硕女，令德来教。式燕且誉，好尔无射。","虽无旨酒？式饮庶几。虽无嘉肴？式食庶几。虽无德与女？式歌且舞？","陟彼高冈，析其柞薪。析其柞薪，其叶湑兮。鲜我觏尔，我心写兮。","高山仰止，景行行止。四牡𬴂𬴂，六辔如琴。觏尔新婚，以慰我心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-217","tags":[]},{"id":"poem-dd3a4dc19f6497c90dee0c81","title":"扇","author":"陆畅","dynasty":"唐","verses":["宝扇持来入禁宫，本教花下动香风。","姮娥须逐彩云降，不可通宵在月中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fcb671fa-4d77-4dd4-859a-40d8be9d1e4c","tags":[]},{"id":"poem-dd3d323cce29459bb1264dc8","title":"句","author":"长孙镒","dynasty":"唐","verses":["霜沾云梦千岩雪，鴈度吴江万木秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9cc7468f-88d7-4a5e-83fe-f0ddbaf7c6e8","tags":[]},{"id":"poem-dd3f57df50b832e90cdc7228","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)小叔知礼攻书，又怎肯怀着恶意？信他人搬喋是非，把亲生兄弟逐出去，每日劝戒不听取。","(贴)同胞共乳，手足之义，割舍把他轻弃，将家私恃长不分取。","小官人晓诗书，知礼义，尽让兄不肯说，他又何曾说是说非？(合)论得来谁是谁不是，何日劝得心意回？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1789","tags":[]},{"id":"poem-dd3f9b5648d49902966da472","title":"园人送瓜","author":"杜甫","dynasty":"唐","verses":["江间虽炎瘴，瓜熟亦不早。","柏公镇夔国，滞务兹一埽。","食新先战士，共少及溪老。","倾筐蒲鸽青，满眼颜色好。","竹竿接嵌窦，引注来鸟道。","沈浮乱水玉，爱惜如芝草。","落刃嚼冰霜，开怀慰枯槁。","许以秋蔕除，仍看小童抱。","东陵迹芜绝，楚汉休征讨。","园人非故侯，种此何草草。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-15c01eb1-1eb8-4d68-b25e-ae244c049afc","tags":[]},{"id":"poem-dd44875f1fe00e7db96f3f10","title":"八","author":"王梵志","dynasty":"唐","verses":["尊人相逐出，子莫向前行。","识事须相逢，（「须相逢」，伯三六五六、伯二八四二卷作「相逢见」。","）情知乏礼生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6a305166-2a40-4dec-a0e6-fbe0ab689a53","tags":[]},{"id":"poem-dd454442bf933e6995fb0764","title":"江村","author":"张乔","dynasty":"唐","verses":["贫游无定踪，乡信转难逢。","寒渚暮烟阔，去帆归思重。","潮平低戍火，木落远山钟。","况是渔家宿，疎篱响夜舂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-47d2fb63-14b0-4633-995b-158213cd4380","tags":[]},{"id":"poem-dd45ab687ae25f9a2de7ecaa","title":"春秋战国门 子贡","author":"周昙","dynasty":"唐","verses":["救鲁亡吴事可伤，谁令利口说田常。","吴亡必定由端木，鲁亦宜其运不长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f189cc0a-1389-47ce-9edb-a0076883f068","tags":[]},{"id":"poem-dd534487230373a2d4590916","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["非弦已断，只是你意慵心懒。","没，你既道是寡鹊孤鸾，又道是昭君宫怨，那更思归别鹤，无非愁叹。","相公，你心里多敢想着谁？(生)不想甚么人。","(贴)你既不然，我理会得了，你道是除了知音听，道我不是知音不与弹。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5091","tags":[]},{"id":"poem-dd589086a21d85a66a0c21fa","title":"咏李","author":"张𬸦","dynasty":"唐","verses":["问李树，如何意不同？应来主毛里，翻入客怀中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c4e3d658-5ce8-4e5a-a9de-00f5d77dbed4","tags":[]},{"id":"poem-dd5c515e9a8e8a982c73b1d1","title":"八月十五日贡院落成宾僚咸集斥世俗之乐不用饮文字也把杯邀月诵香满一轮中句即席赋诗以勉多士","author":"王十朋","dynasty":"宋","verses":["扬辉秋月悬青天，今夕何夕光更圆。","琼为楼台玉为宇，广寒境界移清泉。","月斧云斤天上手，万间突兀摩星斗。","白头郡守呼众宾，共饮落成文字酒。","龙虎群仙上界还，手移桂种栽泉山。","千枝万枝香不断，人人有分行当攀。","姮娥慇勤寄消息，科第要从勤苦得。","丹桂在君书卷中，不须遥向蟾宫觅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-832decee-f4ef-43a2-967a-f74d4356ba92","tags":[]},{"id":"poem-dd5ed2b55bcd9e6606660f65","title":"自涟漪寄薛绍彭","author":"米芾","dynasty":"宋","verses":["老来书兴独未忘，颇得薛老同徜徉。","天下有识推鉴定，龙宫无术疗膏肓。","淮风吹戟稀讼牒，典客闭阁闲壶浆。","吟树对山风景聚，墨池濯砚龟鱼藏。","珠台宝气每贯日，月观桂实时飘香。","银淮烛天限织女，烟海括地生灵光。","俊儿乃是翰墨侣，侠竹不使舆卫将。","象管钿轴映瑞锦，玉鳞棐几铺云肪。","依依烟华动勃鬰，矫矫龙蛇起混茫。","持此以为风月伴，四时之乐乐未央。","部刺不纠翰墨病，圣恩养在林泉乡。","风沙涨天乌帽客，胡不东来从北荒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-500d7edd-f7ef-4e74-a9a0-7585e0246b30","tags":[]},{"id":"poem-dd69cf03134d39e1460999f3","title":"耒阳杜工部墓（题拟）","author":"孟宾于","dynasty":"唐","verses":["南游何感思，更甚叶缤纷。","一夜耒江雨，百年工部文。","青山当日见，白酒至今闻。","惟有为诗者，经过时吊君。","（见钱谦益《笺注杜工部集唱酬题就是》引《耒阳祠志》。","《增修诗话总龟》卷四三引刘斧《摭遗》引「一夜耒江雨，百年工部文」二句，称为「唐人诗」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-eaa78063-2d62-497b-ac47-ad72ffa5f2e0","tags":[]},{"id":"poem-dd6a7a6fe9dbdedac4d95e20","title":"怀方干张为","author":"贯休","dynasty":"唐","verses":["冥搜入仙窟，半夜水堂前。","吾道祗如此，古人多亦然。","萤沈荒坞雾，月苦绿梧蝉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3305e7cf-60ac-4306-87a1-79c080ecb2c7","tags":[]},{"id":"poem-dd6f66ce6a73047e51da9520","title":"抑","author":"佚名","dynasty":"先秦","verses":["抑抑威仪，维德之隅。人亦有言：靡哲不愚，庶人之愚，亦职维疾。","哲人之愚，亦维斯戾。无竞维人，四方其训之。有觉德行，四国顺之。","𬣙谟定命，远犹辰告。敬慎威仪，维民之则。其在于今，兴迷乱于政。","颠覆厥德，荒湛于酒。女虽湛乐从，弗念厥绍。罔敷求先王，克共明刑。","四皇天弗尚，如彼泉流，无沦胥以亡。夙兴夜寐，洒扫庭内，维民之章。","修尔车马，弓矢戎兵，用戒戎作，用逷蛮方。质尔人民，谨尔侯度，用戒不虞。","慎尔出话，敬尔威仪，无不柔嘉。白圭之玷，尚可磨也；斯言之玷，不可为也！","无易由言，无曰苟矣，莫扪朕舌，言不可逝矣。无言不仇，无德不报。","惠于朋友，庶民小子。子孙绳绳，万民靡不承。视尔友君子，辑柔尔颜，不遐有愆。","相在尔室，尚不愧于屋漏。无曰不显，莫予云觏。神之格思，不可度思，矧可射思！","辟尔为德，俾臧俾嘉。淑慎尔止，不愆于仪。不僭不贼，鲜不为则。投我以桃，报之以李。","彼童而角，实虹小子。荏染柔木，言缗之丝。温温恭人，维德之基。","其维哲人，告之话言，顺德之行。其维愚人，覆谓我僭。民各有心。","于乎小子，未知臧否。匪手携之，言示之事。匪面命之，言提其耳。","借曰未知，亦既抱子。民之靡盈，谁夙知而莫成？昊天孔昭，我生靡乐。","视尔梦梦，我心惨惨。诲尔谆谆，听我藐藐。匪用为教，覆用为虐。","借曰未知，亦聿既耄。于乎，小子，告尔旧止。听用我谋，庶无大悔。","天方艰难，曰丧厥国。取譬不远，昊天不忒。回遹其德，俾民大棘。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-255","tags":[]},{"id":"poem-dd73683f595d687fe0c81d87","title":"杂曲歌辞 长干曲四首 二","author":"崔颢","dynasty":"唐","verses":["家临九江水，去来九江侧。","同是长干人，生小不相识。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8d480633-1876-4082-aaca-a7b3a26c04d7","tags":["家乡","女子","热爱","唐诗三百首","乐府"]},{"id":"poem-dd766aa340e78441cb403c1e","title":"千秋节赐群臣镜","author":"明皇帝","dynasty":"唐","verses":["瑞露垂花绶，寒冰澈宝输。","对兹台上月，聊以庆佳辰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-275ae461-9263-47e1-8a47-d477e519c3a9","tags":[]},{"id":"poem-dd7b3de73caa991247f7bed9","title":"夏日题郑谷江上纳凉馆","author":"皎然","dynasty":"唐","verses":["迢遥山意外，清风又对君。","若为于此地，翻作路岐分。","别馆琴徒语，前洲鹤自群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9adfe182-8f7b-4fd7-bef7-78b34ca4c684","tags":[]},{"id":"poem-dd80fd9a2e25847034551f2a","title":"卷耳","author":"佚名","dynasty":"先秦","verses":["采采卷耳，不盈顷筐。嗟我怀人，置彼周行。","陟彼崔嵬，我马虺𬯎。我姑酌彼金罍，维以不永怀。","陟彼高冈，我马玄黄。我姑酌彼兕觥，维以不永伤。","陟彼砠矣，我马瘏矣，我仆痡矣，云何吁矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-2","tags":[]},{"id":"poem-dd83035137eb2045637ac81e","title":"失题","author":"孙处玄","dynasty":"唐","verses":["汉家轻壮士，无状杀彭王。","一遇风尘起，令谁守四方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-197bdcd7-6fc5-4644-a965-96cafe102d90","tags":[]},{"id":"poem-dd832ccd0f9ae6c83eb41d7c","title":"忆秦娥·山重叠","author":"纳兰性德","dynasty":"清","verses":["山重叠。","悬崖一线天疑裂。","天疑裂。","断碑题字，苔痕横啮。","风声雷动鸣金铁。","阴森潭底蛟龙窟。","蛟龙窟。","兴亡满眼，旧时明月。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-34","tags":[]},{"id":"poem-dd8e201bb43645eb573493cc","title":"登龙泉山","author":"陈造","dynasty":"宋","verses":["越山东来万烟鬟，余姚为邑山四环。","客车细穿市井间，邑屋更绕龙泉山。","佛阁翚飞最高处，远近岚霏随指顾。","小留开船有新句，君知可是囚山赋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-ce23b4ea-bfdd-49c5-af9c-d8b7c00a12b1","tags":[]},{"id":"poem-dd908c14d0fb3580292717c4","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["适来它不担那酒米，我婆遂撩拨它说与，改日娘行与你娶贫女。","它欢喜冒雪担至。","你莫道，没这样儿。","苦欺它道没张志！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2519","tags":[]},{"id":"poem-dd922225f97db5ee61e45177","title":"饮散","author":"王镃","dynasty":"宋","verses":["春风吹动漏声残，醉后归来独倚阑。","雨湿落花飞不去，乱红粘满石棋盘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-43d11328-e895-41ac-9df1-cfe59493760b","tags":[]},{"id":"poem-dd93bfeca3bea57b30958b7c","title":"清平乐·上元月蚀","author":"纳兰性德","dynasty":"清","verses":["瑶华映阙，烘散蓂墀雪。","比拟寻常清景别，第一团圆时节。","影蛾忽泛初弦，分辉借与宫莲。","七宝修成合璧，重轮岁岁中天。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-69","tags":[]},{"id":"poem-dda4071e421ebe340245a726","title":"摊破浣溪沙·风絮飘残已化萍","author":"纳兰性德","dynasty":"清","verses":["风絮飘残已化萍，泥莲刚倩藕丝萦。","珍重别拈香一瓣，记前生。","人到情多情转薄，而今真个悔多情。","又到断肠回首处，泪偷零。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-123","tags":[]},{"id":"poem-dda93dd5d8065ad601805974","title":"送谢著作之濠梁","author":"徐铉","dynasty":"宋","verses":["谢客乘轺去，清和景物初。","淮流宜映月，濠上好观鱼。","吏事应微挠，吟情自有余。","偏州莫留滞，东观待繙书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f98cf741-4399-496a-bf1d-468c62c195f5","tags":[]},{"id":"poem-ddbb51368f9bb95ab1aba265","title":"风马儿","author":"萧德祥《小孙屠》","dynasty":"元","verses":["闻得提携寸心喜，来厅下听台旨。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8589","tags":[]},{"id":"poem-ddbe83935e45b18c27155b7a","title":"次蒋元肃韵","author":"王十朋","dynasty":"宋","verses":["酒杯三十六人衔，劝我殷勤不止三。","长记白苹离浙右，忍看丹荔别泉南。","自惭政似阳城拙，那得棠如召伯甘。","见说广文尤惜别，好诗千里送归骖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-78747318-b798-4f7e-822f-97c8aafe0c69","tags":[]},{"id":"poem-ddcd036f9caadee67e298fc4","title":"满庭芳","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(末上)五代残唐，汉刘知远，生时紫雾红光。","李家庄上，招赘做东床。","二舅不容完聚，生巧计拆散鸳行。","三娘受苦，产下咬脐郎。","知远投军，卒发迹到边疆，得遇绣英岳氏，愿配与鸾凰。","一十六岁，咬脐生长，因出猎识认亲娘。","知远加官进职，九州安抚，衣锦还乡。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8791","tags":[]},{"id":"poem-dddbee556c25855ccf39a43c","title":"列女操","author":"孟郊","dynasty":"唐","verses":["梧桐相待老，鸳鸯会双死。","贞女贵狥夫，舍生亦如此。","波澜誓不起，妾心井中水。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a9d3bfca-8402-4946-ad02-53db1964a3b2","tags":["赞颂","妇女","唐诗三百首","乐府"]},{"id":"poem-ddddc0d1b50fbb5b9ac82025","title":"句","author":"贺兰暹","dynasty":"唐","verses":["玉貌自宜双黛翠，桃花独笑一枝春。","秋水未鸣游女佩，寒云空满望夫山。","黄阁暮虫罗户牗，紫庭春草遍阶墀。","绿耳半蔓湘浦竹，骊文乱点武陵花。","辽阳客路千峰引，蓟北乡心片月知。","山云渺渺川程远，木叶萧萧鴈过初。","回鴈不传乡信去，秋风偏向客衣寒。","千峰黛色因晴出，百谷泉声欲暮寒。","黛色迥临沧海上，泉声遥落白云中。","喜遇近臣杨得意，慙非词客马相如。","秋迎晓月鸿声早，日暎深山水气寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c3a5be94-820f-45d8-97f3-206d21ea3023","tags":[]},{"id":"poem-ddece148160bf9b061b3636d","title":"菩萨蛮·谁能画取沙边雨","author":"祖可","dynasty":"宋","verses":["谁能画取沙边雨。","和烟澹扫蒹葭渚。","别岸却斜晖。","采莲人未归。","鸳鸯如解语。","对浴红衣去。","去了更回头。","教侬特地愁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-699","tags":[]},{"id":"poem-de06ed325462492642157d82","title":"重送成都漕","author":"刘跂","dynasty":"宋","verses":["曾游淮上爱清流，况子官为郡督邮。","可贺吕虔贤太守，佩刀应得不须求。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c8be0b09-2e8f-454d-a668-1a2407efca65","tags":[]},{"id":"poem-de09893f36ffe215f119dc42","title":"句","author":"李泌","dynasty":"唐","verses":["青青东门柳，岁晏复憔悴。","良弓摧折久，谁识是龙韬。","旋沫翻成碧玉池，添酥散出琉璃眼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-733cf267-5516-4f52-8110-518c913fe478","tags":[]},{"id":"poem-de0c2fda9e16d870bc291b9f","title":"离富池","author":"陈造","dynasty":"宋","verses":["江流寂无声，明灭窗月晓。","客枕归梦余，意先西蜚鸟。","雪天信少风，翳面正缭绕。","富池忽信次，肯羡雕鹘矫。","向免犯险艰，神惠顾岂少。","今晨有佳兴，调笑向诸小。","波平旗脚直，康庄驰騕褭。","鳞鳞到座隅，健鹊啅林杪。","人家积苏间，山影横练表。","未成官缚去，得句吾事了。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4de168b5-e790-4150-aacc-c3839c840946","tags":[]},{"id":"poem-de14006a79af0dc60bec2ab5","title":"烈文","author":"佚名","dynasty":"先秦","verses":["烈文辟公，锡兹祉福。惠我无疆，子孙保之。无封靡于尔邦，维王其崇之。","念兹戎功，继序其皇之。无竞维人，四方其训之。不显维德，百辟其刑之。于乎，前王不忘！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-268","tags":[]},{"id":"poem-de1548a48a7d5015f3b856b7","title":"偈颂七十一首  其二二","author":"释了惠","dynasty":"宋","verses":["起寨重招五百兵，等闲恢复百余城。","凌烟阁上清风起，留得将军万世名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e3f165cf-08cf-4738-b907-6379e69b85c2","tags":[]}];
